INSERT INTO public.questao VALUES (15452, 1954, 3136, '3418196', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, a respeito de despesa pública e de execução orçamentária e financeira.</p><p style="text-align: left;">O superávit financeiro apurado no balanço patrimonial do exercício anterior, deduzido dos créditos extraordinários abertos no exercício corrente, é fonte de recursos para abertura de créditos suplementares e especiais.</p>', 'Julgue o item a seguir, a respeito de despesa pública e de execução orçamentária e financeira.
