INSERT INTO public.questao VALUES (15554, 1954, 3138, '3144024', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação a receitas, despesas, custos, plano de contas e demonstrações contábeis do setor público, julgue o item seguinte.</p><p style="text-align: left;">São reconhecidos como receita orçamentária os recursos financeiros provenientes de cancelamento de despesas inscritas em restos a pagar.</p>', 'julgue o item seguinte.
