INSERT INTO public.questao VALUES (15555, 1954, 3138, '2271355', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação ao relacionamento entre o regime orçamentário e o regime contábil no setor público, julgue o próximo item.</p><p style="text-align: left;">É efetiva a receita orçamentária que constitui obrigação correspondente, como é o caso das operações de crédito.</p>', 'julgue o próximo item.
É efetiva a receita orçamentária que constitui obrigação correspondente, como é o caso das operações de crédito.', true, '2026-01-29 15:31:15.378398', '2026-01-29 15:31:15.378398', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (15556, 1954, 3138, '2271396', NULL, 'CEBRASPE', '<p style="text-align: left;">Quanto à receita pública, julgue o item subsequente.</p><p style="text-align: left;"><br/>
Em sentido amplo, qualquer entrada de recurso nos cofres públicos é uma receita pública, ainda que exijam uma restituição futura.</p>', 'julgue o item subsequente.
