INSERT INTO public.questao VALUES (15641, 1954, 3139, '1706893', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito da receita pública, julgue o item a seguir.</p><p style="text-align: left;">A doação em espécie recebida por um ente público passa pelas seguintes etapas da receita: lançamento, arrecadação e recolhimento.</p>', 'julgue o item a seguir.
