INSERT INTO public.questao VALUES (15688, 1954, 3141, '2783969', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item seguinte, relacionado à despesa pública.</p><p style="text-align: left;">Classifica-se como global o empenho utilizado para despesas contratuais ou outras de valor determinado e que estejam sujeitas a parcelamento.</p>', 'Julgue o item seguinte, relacionado à despesa pública.
Classifica-se como global o empenho utilizado para despesas contratuais ou outras de valor determinado e que estejam sujeitas a parcelamento.', true, '2026-01-29 15:31:15.378398', '2026-01-29 15:31:15.378398', 'CERTO', '', false);
INSERT INTO public.questao VALUES (15689, 1954, 3141, '2795013', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação a despesas públicas, julgue o item seguinte.</p><p style="text-align: left;"><br/>
O INPI utiliza a modalidade de empenho ordinário para o pagamento das contas de água, gás e luz de sua sede.</p>', 'julgue o item seguinte.
