INSERT INTO public.questao VALUES (15728, 1954, 3141, '2157812', NULL, 'CEBRASPE', '<p style="text-align: left;">Determinado prefeito municipal incluiu receita referente à contratação de estudo técnico de planejamento para obra pública de mobilidade urbana cujo crédito possui vigência de dois anos e foi empenhado em janeiro do primeiro ano.</p><p style="text-align: left;">Acerca dessa situação hipotética, julgue o item a seguir, à luz das disposições da Lei n.º 4.320/1964.</p><p style="text-align: left;">A liquidação dessa despesa dependerá da apuração da importância exata a pagar, independentemente do comprovante da prestação efetiva do serviço, que pode se dar em fase subsequente.</p>', 'julgue o item a seguir, à luz das disposições da Lei n.º 4.320/1964.
