INSERT INTO public.questao VALUES (15759, 1954, 3142, '3599988', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere às alterações orçamentárias e à sua articulação com outros aspectos da execução orçamentária, julgue o item subsequente.</p><p style="text-align: left;"><br/>
