INSERT INTO public.questao VALUES (15777, 1954, 3142, '2395704', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação à programação e à execução orçamentária e financeira, julgue o item a seguir.</p><p style="text-align: left;">No regime de descentralização financeira, a liberação de recursos do orçamento fiscal da União será realizada por meio de repasse, de sub-repasse ou de liberação de cotas.</p>', 'julgue o item a seguir.
