INSERT INTO public.questao VALUES (15779, 1954, 3142, '2590314', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, a respeito da execução orçamentária e financeira do setor público.</p><p style="text-align: left;"><br/>
