INSERT INTO public.questao VALUES (37307, 2000, 4001, '2531765', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca dos conceitos, das formas de uso e das ferramentas do ambiente Windows, julgue o item que se segue.</p><p style="text-align: left;">No MS PowerPoint, a opção para editar os efeitos de transição de eslaides é chamada de Animações.</p>', 'julgue o item que se segue.
