INSERT INTO public.questao VALUES (15780, 1954, 3142, '2638600', NULL, 'CEBRASPE', '<p style="text-align: left;">Quanto à despesa pública, julgue o item a seguir.</p><p style="text-align: left;">As descentralizações orçamentárias, assim como as transposições, não modificam a programação ou o valor das dotações, já que alteram somente a unidade orçamentária detentora do crédito.</p>', 'julgue o item a seguir.
