INSERT INTO public.questao VALUES (15781, 1954, 3142, '1937360', NULL, 'CEBRASPE', '<p style="text-align: left;">Quanto à programação e à execução orçamentária e financeira, julgue o próximo item.</p><p style="text-align: left;">Se o Ministério da Agricultura descentralizou recursos orçamentários para uma de suas secretarias, é correto afirmar que, nesse caso, foi realizado um sub-repasse.</p>', 'julgue o próximo item.
