INSERT INTO public.questao VALUES (15783, 1954, 3142, '2157873', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item que se segue, em relação às etapas e aos estágios das receitas e despesas públicas.</p><p style="text-align: left;">A unidade orçamentária detentora do crédito orçamentário aprovado na lei orçamentária não deve ser alterada quando houver a descentralização de créditos orçamentários.</p>', 'Julgue o item que se segue, em relação às etapas e aos estágios das receitas e despesas públicas.
