INSERT INTO public.questao VALUES (15784, 1954, 3142, '2208641', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, no que se refere ao orçamento público no Brasil e à programação e execução orçamentária e financeira.</p><p style="text-align: left;">Quando ocorre uma descentralização orçamentária, a responsabilidade pela aplicação dos recursos recebidos bem como pela conformidade dos documentos, das informações e dos demonstrativos contábeis, financeiros e operacionais cabe à unidade descentralizadora.</p>', 'Julgue o item a seguir, no que se refere ao orçamento público no Brasil e à programação e execução orçamentária e financeira.
