INSERT INTO public.questao VALUES (15785, 1954, 3142, '2292550', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, referente à programação orçamentária e financeira.</p><p style="text-align: left;">A finalidade básica do decreto de programação orçamentária e financeira e de limitação de empenho e movimentação financeira é acompanhar a execução orçamentária de forma a garantir que a parcela do PPA prevista para o exercício em curso seja efetivamente realizada.</p>', 'Julgue o próximo item, referente à programação orçamentária e financeira.
