INSERT INTO public.questao VALUES (15788, 1954, 3142, '1706878', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando os princípios e a execução orçamentários, bem como a composição orçamentária do DF, julgue o item a seguir.</p><p style="text-align: left;">A movimentação dos recursos entre as unidades do sistema de programação financeira é executada por meio de cotas, repasses e sub-repasses, sendo uma das modalidades de repasse a transferência de recursos de uma empresa pública dependente para um órgão da administração direta de outro ministério.</p>', 'julgue o item a seguir.
A movimentação dos recursos entre as unidades do sistema de programação financeira é executada por meio de cotas, repasses e sub-repasses, sendo uma das modalidades de repasse a transferência de recursos de uma empresa pública dependente para um órgão da administração direta de outro ministério.', true, '2026-01-29 15:31:15.378398', '2026-01-29 15:31:15.378398', 'CERTO', '', false);
INSERT INTO public.questao VALUES (15789, 1954, 3142, '1125430', NULL, 'CEBRASPE', '<p style="text-align: left;">Com base nas normas que regem a contabilidade pública, julgue o item a seguir.</p><p style="text-align: left;">O destaque de determinado crédito orçamentário pode ser realizado independentemente de autorização específica da lei orçamentária anual.</p>', 'julgue o item a seguir.
