INSERT INTO public.questao VALUES (16131, 1955, 3153, '3258628', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca do mandado de injunção, do mandado de segurança e dos Poderes Legislativo e Judiciário, julgue o item a seguir, à luz da jurisprudência do STF.</p><p style="text-align: left;">Não é cabível mandado de injunção para discutir a efetividade de lei regulamentadora já existente.</p>', 'julgue o item a seguir, à luz da jurisprudência do STF.
