INSERT INTO public.questao VALUES (16326, 1955, 3168, '2789209', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando as disposições da Constituição Federal, julgue o item a seguir.</p><p style="text-align: left;">Fiscalizar as concessões de exploração de recursos hídricos é da competência exclusiva dos estados e do Distrito Federal.</p>', 'julgue o item a seguir.
