INSERT INTO public.questao VALUES (26712, 1982, 3695, '2571153', NULL, 'CEBRASPE', '<p style="text-align: left;">Regimentalmente, proposição é toda matéria sujeita à deliberação da Câmara dos Deputados. A este respeito, é lícito afirmar:</p><p style="text-align: left;">parecer é a proposição com que uma Comissão se pronuncia sobre qualquer matéria sujeita a seu estudo, quer se trate de proposição principal, de acessória, ou de matéria ainda não objetivada em proposição.</p>', '', true, '2026-01-30 16:31:37.29402', '2026-01-30 16:31:37.29402', 'CERTO', '', false);
