INSERT INTO public.questao VALUES (18372, 1968, 3272, '3323558', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação a órgãos da governança corporativa e áreas de controle, julgue o próximo item.</p><p style="text-align: left;">O comitê de auditoria é um dos comitês de assessoramento ao conselho de administração.</p>', 'julgue o próximo item.
