INSERT INTO public.questao VALUES (18373, 1968, 3272, '3323559', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação a órgãos da governança corporativa e áreas de controle, julgue o próximo item.</p><p style="text-align: left;">Os conselhos de administração são órgãos, estatutários ou não, que auxiliam a governança corporativa.</p>', 'julgue o próximo item.
