INSERT INTO public.questao VALUES (18375, 1968, 3272, '3323562', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação a órgãos da governança corporativa e áreas de controle, julgue o próximo item.</p><p style="text-align: left;">A ouvidoria deve promover tratamento justo a todas as partes interessadas, levando em consideração os respectivos direitos, deveres, necessidades, interesses e expectativas.</p>', 'julgue o próximo item.
