INSERT INTO public.questao VALUES (18379, 1968, 3272, '3323619', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere à estratégia em projetos, julgue o seguinte item.</p><p style="text-align: left;">Um sistema de governança corporativa bem estruturado implica a eliminação de riscos estratégicos e operacionais.</p>', 'julgue o seguinte item.
