INSERT INTO public.questao VALUES (18380, 1968, 3272, '3323628', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere à estratégia em projetos, julgue o seguinte item.</p><p style="text-align: left;">A ausência de análise de riscos em um projeto pode comprometer o alinhamento estratégico e levar a desvios nos resultados esperados pela organização.</p>', 'julgue o seguinte item.
A ausência de análise de riscos em um projeto pode comprometer o alinhamento estratégico e levar a desvios nos resultados esperados pela organização.', true, '2026-01-29 17:44:58.855528', '2026-01-29 17:44:58.855528', 'CERTO', '', false);
INSERT INTO public.questao VALUES (18381, 1968, 3272, '3323662', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de sustentabilidade e ética em projetos, de gestão de aquisições, auditorias, governança e compliance, julgue o item a seguir.</p><p style="text-align: left;"><br/>
