INSERT INTO public.questao VALUES (18412, 1968, 3272, '3455408', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando as teorias que alicerçam a governança corporativa, julgue o item a seguir.</p><p style="text-align: left;"><br/>
