INSERT INTO public.questao VALUES (18413, 1968, 3272, '3455409', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando as teorias que alicerçam a governança corporativa, julgue o item a seguir.</p><p style="text-align: left;">A teoria da agência aborda o conflito de interesses entre os acionistas e os gestores, sugerindo mecanismos de controle e incentivos para o alinhamento dos objetivos de ambos.</p>', 'julgue o item a seguir.
