INSERT INTO public.questao VALUES (18414, 1968, 3272, '3455410', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando as teorias que alicerçam a governança corporativa, julgue o item a seguir.</p><p style="text-align: left;">De acordo com a teoria da dependência de recursos, a sobrevivência organizacional depende da capacidade de gerenciamento das dependências externas e do acesso a recursos críticos.</p>', 'julgue o item a seguir.
