INSERT INTO public.questao VALUES (18416, 1968, 3272, '3455414', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando o disposto na legislação que trata da prevenção e combate à lavagem de dinheiro, bem como os principais órgãos da governança corporativa, julgue o item subsequente.</p><p style="text-align: left;"><br/>
