INSERT INTO public.questao VALUES (18417, 1968, 3272, '3455441', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando o disposto na legislação que trata da prevenção e combate à lavagem de dinheiro, bem como os principais órgãos da governança corporativa, julgue o item subsequente.</p><p style="text-align: left;">A assembleia geral é o órgão máximo de deliberação nas sociedades anônimas, responsável por decisões como a eleição de administradores e aprovação de contas.</p>', 'julgue o item subsequente.
