INSERT INTO public.questao VALUES (18470, 1968, 3277, '3291885', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, a respeito de gestão de relacionamento.</p><p style="text-align: left;">No processo de elaboração de um plano de negócio, as decisões estratégicas podem ser embasadas apenas na intuição dos gestores e nas tendências observadas de forma empírica, o que dispensaria a etapa de análise de mercado.</p>', 'Julgue o item a seguir, a respeito de gestão de relacionamento.
