INSERT INTO public.questao VALUES (18471, 1968, 3277, '3291956', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o seguinte item, relativo à gestão estratégica.</p><p style="text-align: left;">Planejamento estratégico é um conjunto de ações e definições de processos de desenvolvimento de código estratégico para gestão.</p>', 'Julgue o seguinte item, relativo à gestão estratégica.
Planejamento estratégico é um conjunto de ações e definições de processos de desenvolvimento de código estratégico para gestão.', true, '2026-01-29 17:44:58.855528', '2026-01-29 17:44:58.855528', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (18472, 1968, 3277, '3293955', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de processos administrativos, julgue o item a seguir.</p><p style="text-align: left;">Na elaboração do planejamento estratégico, a organização define que objetivos quer alcançar.</p>', 'julgue o item a seguir.
