INSERT INTO public.questao VALUES (18954, 1968, 3289, '767846', NULL, 'CEBRASPE', '<p style="text-align: left;">
		Acerca dos princípios fundamentais que regem a administração pública federal, julgue o item a seguir.</p><p style="text-align: left;">
		O princípio da delegação de competência objetiva assegurar maior rapidez e objetividade às decisões, sendo a delegação de caráter facultativo e permanente.</p>', 'julgue o item a seguir.
		O princípio da delegação de competência objetiva assegurar maior rapidez e objetividade às decisões, sendo a delegação de caráter facultativo e permanente.', true, '2026-01-29 17:44:58.855528', '2026-01-29 17:44:58.855528', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (18955, 1968, 3291, '3293966', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca dos tipos de departamentalização, da organização informal e da cultura organizacional, julgue o item que se segue.</p><p style="text-align: left;">Nos grupos informais, os padrões de relações e de atitudes aceitos e assimilados pelas pessoas são desenvolvidos espontaneamente, contudo os padrões de desempenho organizacional sempre correspondem aos estabelecidos pela administração da instituição.</p>', 'julgue o item que se segue.
Nos grupos informais, os padrões de relações e de atitudes aceitos e assimilados pelas pessoas são desenvolvidos espontaneamente, contudo os padrões de desempenho organizacional sempre correspondem aos estabelecidos pela administração da instituição.', true, '2026-01-29 17:44:58.855528', '2026-01-29 17:44:58.855528', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (18956, 1968, 3291, '3296149', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de avaliação de desempenho, resultados, flexibilidade organizacional e trabalho em equipe, julgue o item subsecutivo.</p><p style="text-align: left;"><br/>
