INSERT INTO public.questao VALUES (18958, 1968, 3291, '3304902', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, a respeito de aspectos do comportamento interpessoal dos colaboradores, do trabalho em equipe e da opinião dos usuários sobre o serviço prestado.</p><p style="text-align: left;">O autoconhecimento, para o melhor desempenho nas equipes de trabalho, pode ser desenvolvido por meio da análise dos pontos fortes e fracos, mas não pela compreensão das dificuldades encontradas no dia a dia.</p>', 'Julgue o item a seguir, a respeito de aspectos do comportamento interpessoal dos colaboradores, do trabalho em equipe e da opinião dos usuários sobre o serviço prestado.
