INSERT INTO public.questao VALUES (18959, 1968, 3291, '3305172', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsequente, relativo a trabalho em equipe, motivação e diversidade organizacional.</p><p style="text-align: left;"><br/>
