INSERT INTO public.questao VALUES (18960, 1968, 3291, '3305174', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsequente, relativo a trabalho em equipe, motivação e diversidade organizacional.</p><p style="text-align: left;">A equipe de trabalho funcional é constituída por colaboradores do mesmo nível hierárquico, mas com habilidades, técnicas e formação em áreas diferentes.</p>', 'Julgue o item subsequente, relativo a trabalho em equipe, motivação e diversidade organizacional.
