INSERT INTO public.questao VALUES (18961, 1968, 3291, '3305182', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsequente, relativo a trabalho em equipe, motivação e diversidade organizacional.</p><p style="text-align: left;">A personalidade dos integrantes de uma equipe influencia significativamente os relacionamentos interpessoais, sendo inevitáveis os conflitos interpessoais, que sempre prejudicam o desempenho da equipe, independentemente do modo como sejam gerenciados.</p>', 'Julgue o item subsequente, relativo a trabalho em equipe, motivação e diversidade organizacional.
