INSERT INTO public.questao VALUES (18977, 1968, 3291, '3348368', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere à gestão de equipes e grupos de trabalho nas organizações, julgue o item seguinte.</p><p style="text-align: left;">Uma das funções organizacionais que os grupos formais exercem nas organizações é a implementação de decisõescomplexas.</p>', 'julgue o item seguinte.
