INSERT INTO public.questao VALUES (18965, 1968, 3291, '3305732', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item seguinte, em relação ao trabalho em equipe e ao relacionamento interpessoal.</p><p style="text-align: left;">Para o sucesso do trabalho em equipe, cada membro deve evitar expressar suas opiniões pessoais e deve focar nos objetivos práticos do projeto, garantindo alinhamento e produtividade</p>', 'Julgue o item seguinte, em relação ao trabalho em equipe e ao relacionamento interpessoal.
