INSERT INTO public.questao VALUES (18966, 1968, 3291, '3315770', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere à integração grupal, julgue o item subsecutivo.</p><p style="text-align: left;"><br/>
