INSERT INTO public.questao VALUES (18967, 1968, 3291, '3315771', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere à integração grupal, julgue o item subsecutivo.</p><p style="text-align: left;">O grupo de referência é aquele em relação ao qual o indivíduo sente-se motivado a manter relações.</p>', 'julgue o item subsecutivo.
