INSERT INTO public.questao VALUES (18968, 1968, 3291, '3315772', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere à integração grupal, julgue o item subsecutivo.</p><p style="text-align: left;">A comunicação é condição fundamental para o funcionamento dos grupos, dentro e fora das organizações.</p>', 'julgue o item subsecutivo.
