INSERT INTO public.questao VALUES (19006, 1968, 3292, '3305030', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de gestão de processos nas organizações públicas, julgue o item que se segue.</p><p style="text-align: left;"><br/>
