INSERT INTO public.questao VALUES (19008, 1968, 3292, '3305046', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de gestão de processos nas organizações públicas, julgue o item que se segue.</p><p style="text-align: left;">O diagrama de blocos é um fluxograma simples que se destina a ilustrar as etapas de um processo, subprocesso, atividade ou tarefa.</p>', 'julgue o item que se segue.
