INSERT INTO public.questao VALUES (19009, 1968, 3292, '3313308', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de gestão de processos e gestão da qualidade, julgue o próximo item.</p><p style="text-align: left;">Um processo de gerenciamento de serviços que agrega valor ao cliente caracteriza-se como um processo interfuncional ponta a ponta, sendo, portanto, considerado um processo primário.</p>', 'julgue o próximo item.
