INSERT INTO public.questao VALUES (19010, 1968, 3292, '3313310', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de gestão de processos e gestão da qualidade, julgue o próximo item.</p><p style="text-align: left;">Os processos de suporte têm a finalidade estrita de prover o suporte aos processos primários.</p>', 'julgue o próximo item.
