INSERT INTO public.questao VALUES (19011, 1968, 3292, '3317119', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item seguinte, a respeito de gestão de projetos, gestão de processos, ciclo PDCA e<em> benchmarking.</em></p><p style="text-align: left;">A compreensão dos processos organizacionais no contexto das metas almejadas, a detecção de problemas e a qualidade dos produtos são aspectos que devem ser considerados na análise de processos.</p>', 'Julgue o item seguinte, a respeito de gestão de projetos, gestão de processos, ciclo PDCA e
 benchmarking.
