INSERT INTO public.questao VALUES (19016, 1968, 3292, '3421279', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito da gestão por processos, julgue o item a seguir.</p><p style="text-align: left;">O mapeamento dos processos é condição necessária à realização das atividades cotidianas que visam à concretização dos objetivos estratégicos.</p>', 'julgue o item a seguir.
