INSERT INTO public.questao VALUES (19017, 1968, 3292, '3421282', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito da gestão por processos, julgue o item a seguir.</p><p style="text-align: left;">O mapeamento de processos, conquanto impossibilite a identificação dos fatores críticos, permite a determinação dos diversos agentes internos e externos envolvidos no processo.</p>', 'julgue o item a seguir.
