INSERT INTO public.questao VALUES (19018, 1968, 3292, '3421289', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito da gestão por processos, julgue o item a seguir.</p><p style="text-align: left;">O mapofluxograma é utilizado antes do início do trabalho, para a identificação dos elementos pertinentes de um projeto de melhoria de processo.</p>', 'julgue o item a seguir.
