INSERT INTO public.questao VALUES (19020, 1968, 3292, '3441036', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, acerca da abordagem por processos, das técnicas de análise e dos indicadores de processos.</p><p style="text-align: left;">Como os processos de gestão não atribuem valor diretamente aos clientes, eles não são fundamentais para a garantia da eficiência e eficácia das operações organizacionais.</p>', 'Julgue o próximo item, acerca da abordagem por processos, das técnicas de análise e dos indicadores de processos.
