INSERT INTO public.questao VALUES (19022, 1968, 3292, '3441039', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, acerca da abordagem por processos, das técnicas de análise e dos indicadores de processos.</p><p style="text-align: left;">Na construção de indicadores de processos, é adequado o estabelecimento de indicadores direcionadores, os quais monitoram as causas após o efeito e não permitem que se altere o resultado.</p>', 'Julgue o próximo item, acerca da abordagem por processos, das técnicas de análise e dos indicadores de processos.
