INSERT INTO public.questao VALUES (19024, 1968, 3292, '3441970', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de gestão de processos, julgue o item subsequente.</p><p style="text-align: left;">A cadeia de valor divide a organização em atividades de criação de valor, o que favorece a compreensão do comportamento dos custos e das potenciais fontes de diferenciação competitiva.</p>', 'julgue o item subsequente.
