INSERT INTO public.questao VALUES (19025, 1968, 3292, '3441972', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de gestão de processos, julgue o item subsequente.</p><p style="text-align: left;">O mapeamento de processos, técnica que permite visualizar todas as etapas de um processo, facilita a identificação de gargalos e oportunidades de melhoria.</p>', 'julgue o item subsequente.
