INSERT INTO public.questao VALUES (19179, 1968, 3298, '3361090', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, referente aos processos participativos de gestão pública.</p><p style="text-align: left;"><br/>
