INSERT INTO public.questao VALUES (19180, 1968, 3298, '3361385', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, relativo aos processos participativos de gestão pública e à excelência nos serviços públicos.</p><p style="text-align: left;"><br/>
