INSERT INTO public.questao VALUES (19181, 1968, 3298, '3596767', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito da gestão por resultados na produção de serviços públicos e da gestão de pessoas por competências, julgue o item que se segue.</p><p style="text-align: left;"><br/>
