INSERT INTO public.questao VALUES (32320, 1969, 3732, '1704598', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de administração pública, julgue o item a seguir.</p><p style="text-align: left;">O alcance das metas físico- financeiras de determinada política pública garante a efetivação das mudanças desejadas na sociedade.</p>', 'julgue o item a seguir.
