INSERT INTO public.questao VALUES (32610, 1971, 3573, '345202', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsequente, relativo à administração pública direta e indireta.</p><p style="text-align: left;">São características das agências reguladoras a autonomia e o mandato fixo de seus dirigentes.</p>', 'Julgue o item subsequente, relativo à administração pública direta e indireta.
