INSERT INTO public.questao VALUES (26213, 1982, 3683, '2145789', NULL, 'CEBRASPE', '<p>Julgue o item a seguir, de acordo com a Resolução nº 1/1970, que dispõe sobre o Regimento Comum do Congresso Nacional.</p><p>As sessões somente serão abertas com a presença mínima de 1/6 da composição de cada Casa do Congresso.</p>', 'Julgue o item a seguir, de acordo com a Resolução nº 1/1970, que dispõe sobre o Regimento Comum do Congresso Nacional.
