INSERT INTO public.questao VALUES (32611, 1971, 3573, '348207', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca da administração pública, julgue o item a seguir.</p><p style="text-align: left;">As agências reguladoras são entidades paraestatais que atuam no domínio econômico, cuja atuação é voltada à regulação de mercado.</p>', 'julgue o item a seguir.
