INSERT INTO public.questao VALUES (26215, 1982, 3683, '2145791', NULL, 'CEBRASPE', '<p>Julgue o item a seguir, de acordo com a Resolução nº 1/1970, que dispõe sobre o Regimento Comum do Congresso Nacional.</p><p>A apreciação das matérias será feita em um só turno de discussão e votação.</p>', 'Julgue o item a seguir, de acordo com a Resolução nº 1/1970, que dispõe sobre o Regimento Comum do Congresso Nacional.
