INSERT INTO public.questao VALUES (26249, 1982, 3683, '1764562', NULL, 'CEBRASPE', '<p style="text-align: left;">Após o encerramento da discussão de determinada matéria no Congresso Nacional,</p><p style="text-align: left;">a redação final do projeto deverá ser elaborada pela respectiva comissão mista.</p>', '', true, '2026-01-30 16:31:37.29402', '2026-01-30 16:31:37.29402', 'CERTO', '', false);
INSERT INTO public.questao VALUES (26250, 1982, 3683, '1764563', NULL, 'CEBRASPE', '<p style="margin: 0cm 0cm 8pt; text-align: left;">Após o encerramento da discussão de determinada matéria no Congresso Nacional,</p><p style="margin: 0cm 0cm 8pt; text-align: left;">a votação poderá ser encaminhada por quatro senadores e quatro deputados.</p>', '', true, '2026-01-30 16:31:37.29402', '2026-01-30 16:31:37.29402', 'CERTO', '', false);
INSERT INTO public.questao VALUES (38137, 2002, 4029, '2981692', NULL, 'CEBRASPE', '<p style="text-align: left;">Sobre ataques do tipo<em> phishing,</em> julgue o item a seguir.</p><p style="text-align: left;"><br/>
