INSERT INTO public.questao VALUES (19235, 1968, 3301, '2935310', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsequente, a respeito de gestão de pessoas.</p><p style="text-align: left;">No processo de gestão de pessoas, é necessário conciliar os objetivos dos colaboradores com os da organização para que haja engajamento, motivação e alcance dos resultados estratégicos.</p>', 'Julgue o item subsequente, a respeito de gestão de pessoas.
