INSERT INTO public.questao VALUES (19273, 1968, 3302, '2783713', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere ao trabalho em equipe e aos aspectos de personalidade, relacionamento e eficácia no comportamento interpessoal nele envolvidos, julgue o item seguinte.</p><p style="text-align: left;">O exercício de receber <em>feedback </em>é importante para identificar o desempenho individual em relação aos objetivos da organização, sem apresentar relevância para o desenvolvimento do autoconhecimento.</p>', 'julgue o item seguinte.
