INSERT INTO public.questao VALUES (19483, 1973, 3306, '3255338', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação ao gerenciamento de projetos, julgue o item a seguir.</p><p style="text-align: left;">O projeto é um esforço eventual, ou seja, empregado temporariamente para se criar um resultado único, um produto ou um serviço.</p>', 'julgue o item a seguir.
