INSERT INTO public.questao VALUES (19489, 1973, 3306, '3292124', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação à gerência de projetos, julgue o item a seguir.</p><p style="text-align: left;">Um programa envolve projetos relacionados, programas subsidiários e atividades do programa gerenciadas de forma independente e cujos benefícios são indisponíveis na gestão individual.</p>', 'julgue o item a seguir.
