INSERT INTO public.questao VALUES (19490, 1973, 3306, '3292126', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de processos do PMBOK, julgue o item subsequente.</p><p style="text-align: left;"><br/>
