INSERT INTO public.questao VALUES (19493, 1973, 3306, '3294425', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, referente à ética e à cultura organizacional em gerenciamento de projetos.</p><p style="text-align: left;">A cultura organizacional tem um impacto significativo na eficácia da execução dos projetos e no seu sucesso dentro de uma organização, ao influenciar a comunicação, a colaboração e a adesão aos processos.</p>', 'Julgue o item a seguir, referente à ética e à cultura organizacional em gerenciamento de projetos.
