INSERT INTO public.questao VALUES (19496, 1973, 3306, '3313226', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsequente, relativo à gestão de projetos e processos.</p><p style="text-align: left;">Programas consistem em conjuntos de projetos gerenciados de forma unificada.</p>', 'Julgue o item subsequente, relativo à gestão de projetos e processos.
Programas consistem em conjuntos de projetos gerenciados de forma unificada.', true, '2026-01-29 17:44:58.855528', '2026-01-29 17:44:58.855528', 'CERTO', '', false);
INSERT INTO public.questao VALUES (19497, 1973, 3306, '3313317', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item seguinte, a respeito de gestão de projetos e planejamento estratégico.</p><p style="text-align: left;">O modo de execução de projetos é influenciado pelo ambiente, pela estrutura organizacional e pelo grau de maturidade da organização em relação ao gerenciamento.</p>', 'Julgue o item seguinte, a respeito de gestão de projetos e planejamento estratégico.
