INSERT INTO public.questao VALUES (19687, 1973, 3316, '3544581', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item seguinte, relativos à função de controle na administração pública e à gestão de projetos.</p><p style="text-align: left;">Tendo em vista que as organizações esperam que os projetos entreguem resultados, além de produtos e artefatos, os gerentes de projeto devem entregar projetos que criem valor para a organização e as partes interessadas, no contexto do sistema por entrega de valor da organização.</p>', 'Julgue o item seguinte, relativos à função de controle na administração pública e à gestão de projetos.
Tendo em vista que as organizações esperam que os projetos entreguem resultados, além de produtos e artefatos, os gerentes de projeto devem entregar projetos que criem valor para a organização e as partes interessadas, no contexto do sistema por entrega de valor da organização.', true, '2026-01-29 17:44:58.855528', '2026-01-29 17:44:58.855528', 'CERTO', '', false);
INSERT INTO public.questao VALUES (37308, 2000, 4001, '2705006', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item que se segue, relativos a MSOffice M365 (Word, Excel, PowerPoint, OneDrive, Sharepoint e Teams).</p><p style="text-align: left;">O Microsoft PowerPoint é uma ferramenta utilizada para criar sites interativos de forma dinâmica.</p>', 'Julgue o item que se segue, relativos a MSOffice M365 (Word, Excel, PowerPoint, OneDrive, Sharepoint e Teams).
