INSERT INTO public.questao VALUES (27082, 1982, 3705, '2588227', NULL, 'CEBRASPE', '<p>Julgue o item a seguir de acordo com o Código de Ética e Decoro Parlamentar da Câmara dos Deputados.</p><p>Abusar das prerrogativas constitucionais asseguradas aos membros do Congresso Nacional e perceber vantagens indevidas, em proveito próprio ou de outrem, no exercício da atividade parlamentar, constituem procedimentos incompatíveis com o decoro parlamentar, puníveis com a perda do mandato.</p>', 'Julgue o item a seguir de acordo com o Código de Ética e Decoro Parlamentar da Câmara dos Deputados.
Abusar das prerrogativas constitucionais asseguradas aos membros do Congresso Nacional e perceber vantagens indevidas, em proveito próprio ou de outrem, no exercício da atividade parlamentar, constituem procedimentos incompatíveis com o decoro parlamentar, puníveis com a perda do mandato.', true, '2026-01-30 16:31:37.29402', '2026-01-30 16:31:37.29402', 'CERTO', '', false);
