INSERT INTO public.questao VALUES (26949, 1982, 3696, '2617353', NULL, 'CEBRASPE', '<p>Julgue o item a seguir de acordo com a Resolução nº 17, de 1989, que aprova o Regimento Interno da Câmara dos Deputados.</p><p>Após o recebimento da denúncia de crime de responsabilidade pelo Presidente da Câmara, o acusado será notificado e terá a oportunidade de se manifestar, se assim desejar, dentro de um prazo de quinze sessões.</p>', 'Julgue o item a seguir de acordo com a Resolução nº 17, de 1989, que aprova o Regimento Interno da Câmara dos Deputados.
Após o recebimento da denúncia de crime de responsabilidade pelo Presidente da Câmara, o acusado será notificado e terá a oportunidade de se manifestar, se assim desejar, dentro de um prazo de quinze sessões.', true, '2026-01-30 16:31:37.29402', '2026-01-30 16:31:37.29402', 'ERRADO', '', false);
