INSERT INTO public.questao VALUES (28122, 1969, 3730, '255660', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito da teoria política, julgue o item subsecutivo.</p><p style="text-align: left;">Segundo Pierre Bourdieu, campo político deve ser definido como um microcosmo composto de propriedades, ações, reações e processos totalmente dependentes do macrocosmo social.</p>', 'julgue o item subsecutivo.
