INSERT INTO public.questao VALUES (27017, 1982, 3702, '2621214', NULL, 'CEBRASPE', '<p>Julgue o item a seguir de acordo com a Resolução nº 17, de 1989, que aprova o Regimento Interno da Câmara dos Deputados.</p><p>Outras formas de participação da sociedade civil recebidas pela Comissão de Legislação Participativa serão direcionadas à Mesa. A partir daí, serão distribuídas à Comissão ou Comissões apropriadas para avaliação do mérito respectivo, ou à Ouvidoria, dependendo do caso.</p>', 'Julgue o item a seguir de acordo com a Resolução nº 17, de 1989, que aprova o Regimento Interno da Câmara dos Deputados.
Outras formas de participação da sociedade civil recebidas pela Comissão de Legislação Participativa serão direcionadas à Mesa. A partir daí, serão distribuídas à Comissão ou Comissões apropriadas para avaliação do mérito respectivo, ou à Ouvidoria, dependendo do caso.', true, '2026-01-30 16:31:37.29402', '2026-01-30 16:31:37.29402', 'CERTO', '', false);
INSERT INTO public.questao VALUES (37171, 2000, 3997, '2988072', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação ao pacote Microsoft Office 365, julgue o item a seguir.</p><p style="text-align: left;">O Microsoft Office 365 disponibiliza funcionalidade que ajuda a garantir que os arquivos do Word estejam acessíveis para pessoas com deficiências; por meio dessa ferramenta, pode-se verificar o arquivo e detectar um conjunto de regras que identifica possíveis problemas de acessibilidade.</p>', 'julgue o item a seguir.
O Microsoft Office 365 disponibiliza funcionalidade que ajuda a garantir que os arquivos do Word estejam acessíveis para pessoas com deficiências; por meio dessa ferramenta, pode-se verificar o arquivo e detectar um conjunto de regras que identifica possíveis problemas de acessibilidade.', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'CERTO', '', false);
