INSERT INTO public.questao VALUES (27987, 1988, 3727, '925899', NULL, 'CEBRASPE', '<p style="text-align: left;">
	Depois de muitas crises, de alternância entre períodos democráticos e autoritários, a República brasileira completa 120 anos em 2009. O colapso do regime militar, em 1985, possibilitou o retorno do poder civil e a construção de uma democracia mais sólida e menos formal, cujo símbolo maior é a Constituição Federal de 1988. Assinale a opção que não representa característica, nos dias de hoje, da República brasileira.<br/></p>', '', true, '2026-01-30 17:20:18.352159', '2026-01-30 17:20:18.352159', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (27988, 1988, 3727, '8582', NULL, 'CEBRASPE', 'O processo político brasileiro recente revela uma profunda fragmentação 
da sociedade com efeitos diretos na proliferação de partidos políticos 
que não possuem uma clara diferenciação entre si. Como conseqüência 
desse fato, a representação de interesses da sociedade e as relações 
entre os Poderes Executivo e Legislativo têm peculiaridades bastante 
demarcadas no caso brasileiro. Com o auxílio dessa afirmação, julgue os 
itens seguintes.<br/><br/>O sistema de representação na Câmara dos Deputados retrata fielmente a distribuição do número de eleitores por unidade da Federação.<br/>', 'julgue os 
itens seguintes.
O sistema de representação na Câmara dos Deputados retrata fielmente a distribuição do número de eleitores por unidade da Federação.', true, '2026-01-30 17:20:18.352159', '2026-01-30 17:20:18.352159', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (27989, 1988, 3728, '2796701', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação ao cenário global contemporâneo, julgue o item a seguir.</p><p style="text-align: left;">O Oriente Médio vem atraindo a atenção do mundo, seja por sua importância econômica internacional, seja pelos recorrentes conflitos existentes na região.</p>', 'julgue o item a seguir.
