INSERT INTO public.questao VALUES (27990, 1988, 3728, '2796743', NULL, 'CEBRASPE', '<p style="text-align: left;">O modelo atual de desenvolvimento permite avanços materiais notáveis, mas também potencializa efeitos danosos ao meio ambiente, como as mudanças climáticas. Em relação a esse tema, julgue o item seguinte.</p><p style="text-align: left;">Entre a luta pela paz e as pressões das grandes potências mundiais, os cinco membros permanentes do conselho de segurança da Organização das Nações Unidas (ONU) abdicaram-se de promover encontros multilaterais voltados para a questão ambiental.</p>', 'julgue o item seguinte.
Entre a luta pela paz e as pressões das grandes potências mundiais, os cinco membros permanentes do conselho de segurança da Organização das Nações Unidas (ONU) abdicaram-se de promover encontros multilaterais voltados para a questão ambiental.', true, '2026-01-30 17:20:18.352159', '2026-01-30 17:20:18.352159', 'ERRADO', '', false);
