INSERT INTO public.questao VALUES (28042, 1988, 3728, '738813', NULL, 'CEBRASPE', '<p style="text-align: center;"><strong>Líderes coreanos encerram cúpula em ‘montanha sagrada’ na Coreia do Norte</strong></p><p style="text-align: left;">
