INSERT INTO public.questao VALUES (28043, 1988, 3728, '738811', NULL, 'CEBRASPE', '<p style="text-align: center;"><strong>Líderes coreanos encerram cúpula em ‘montanha sagrada’ na Coreia do Norte</strong></p><p style="text-align: left;">
