INSERT INTO public.questao VALUES (28803, 1990, 3745, '1790911', NULL, 'CEBRASPE', '<p style="text-align: left;">Ainda acerca dos sistemas eleitorais, julgue o item subsequente.</p><p style="text-align: left;">Os especialistas concordam que mudanças fundamentais nos sistemas eleitorais ocorrem apenas em situações históricas extraordinárias.</p>', 'julgue o item subsequente.
