INSERT INTO public.questao VALUES (37175, 2000, 3997, '3039360', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, a respeito de MS Office, MS Word, MS Excel e MS PowerPoint.</p><p style="text-align: left;">Ao se editar uma tabela no Word, o menu Layout permite formatar linhas ou colunas de tabelas simples, de grade e de lista; enquanto o menu Design é usado para seleção, exclusão e inserção de linhas e colunas e alinhamento das células.</p>', 'Julgue o próximo item, a respeito de MS Office, MS Word, MS Excel e MS PowerPoint.
