INSERT INTO public.questao VALUES (37008, 2000, 3993, '2775421', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito dos conceitos básicos de computadores, julgue o item a seguir.</p><p style="text-align: left;">Para que um computador possa se conectar à Internet, é essencial que ele esteja equipado com um <em>hardwar</em>e de comunicação, denominado placa de rede, que pode ser um<em> chipset</em> integrado à placa mãe do computador.</p>', 'julgue o item a seguir.
