INSERT INTO public.questao VALUES (37009, 2000, 3993, '3202761', NULL, 'CEBRASPE', '<p style="text-align: left;">O computador é um equipamento eletrônico utilizado para manipular informações dos mais variados tipos, como textos, fotos, desenhos, planilhas de cálculos, músicas, vídeos, entre outros. A esse respeito, julgue o próximo item.</p><p style="text-align: left;"><br/>
