INSERT INTO public.questao VALUES (37036, 2000, 3994, '2395650', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item seguinte, relativo ao sistema operacional Windows 10.</p><p style="text-align: left;"><br/>
