INSERT INTO public.questao VALUES (37041, 2000, 3994, '2421493', NULL, 'CEBRASPE', '<p style="text-align: left;">No que diz respeito à organização e gerenciamento de arquivos e pastas e ao armazenamento de dados em nuvem, julgue o item seguinte.</p><p style="text-align: left;"><br/>
