INSERT INTO public.questao VALUES (29529, 1994, 3776, '3427766', NULL, 'CEBRASPE', '<p style="text-align:center"><div style="overflow-x: auto; display: inline-block; max-width: 100%; padding: 1px 0"><img src="https://cdn.tecconcursos.com.br/figuras/d18e0225-68f0-4db3-aedd-dcab531d2842"/></div></p><p style="text-align:right"><span style="">Internet:&lt;croplifela.org&gt;.</span></p><p>Judge the following item based on the infographic above.</p><p>Due to climate change, droughts are happening as fast as floods.</p>', 'Judge the following item based on the infographic above. Due to climate change, droughts are happening as fast as floods.', true, '2026-01-30 18:26:23.6685', '2026-01-30 18:26:23.6685', 'ERRADO', 'https://cdn.tecconcursos.com.br/figuras/d18e0225-68f0-4db3-aedd-dcab531d2842', false);
