INSERT INTO public.questao VALUES (37087, 2000, 3994, '577050', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item, relativo aos sistemas operacionais Linux e Windows e ao editor de texto Microsoft Word 2013.</p><p style="text-align: left;">O Windows 10 pode ser configurado para que, ao se clicar o menu Iniciar, seja disponibilizada uma lista de aplicativos instalados no computador, classificados em ordem alfabética.</p>', 'Julgue o item, relativo aos sistemas operacionais Linux e Windows e ao editor de texto Microsoft Word 2013.
