INSERT INTO public.questao VALUES (31612, 1968, 3829, '3258925', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação às abordagens teóricas da administração, às funções administrativas, e à estrutura e à cultura organizacionais, julgue o item a seguir.</p><p style="text-align: left;">Entre as vantagens da abordagem burocrática da administração estão a facilidade de ajustamento às mudanças organizacionais e a personalização do relacionamento entre os colaboradores.</p>', 'julgue o item a seguir.
