INSERT INTO public.questao VALUES (31722, 1968, 3830, '2589048', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsequente, a respeito dos modelos de governança e dos aspectos da administração pública burocrática e gerencial.</p><p style="text-align: left;"><br/>
