INSERT INTO public.questao VALUES (31725, 1968, 3830, '2724542', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca da gestão de resultados, das convergências e diferenças entre gestão pública e privada e do paradigma do cliente na gestão pública, julgue o próximo item.</p><p style="text-align: left;">Para o cliente da gestão pública brasileira, o Estado tem deixado de exercer o seu papel regulador, que é caracterizado pela atuação direta na economia, para atender ao interesse coletivo.</p>', 'julgue o próximo item.
