INSERT INTO public.questao VALUES (31728, 1968, 3830, '1503585', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, no que se às reformas administrativas, à reforma do aparelho do Estado, ao Estado regulador e aos processos participativos de gestão pública.</p><p style="text-align: left;">Na administração pública gerencial, a responsabilização dos administradores pelos atos decorrentes do exercício da função pública é procedimento essencial à defesa dos princípios republicanos.</p>', 'Julgue o próximo item, no que se às reformas administrativas, à reforma do aparelho do Estado, ao Estado regulador e aos processos participativos de gestão pública.
