INSERT INTO public.questao VALUES (31729, 1968, 3830, '1503587', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, no que se às reformas administrativas, à reforma do aparelho do Estado, ao Estado regulador e aos processos participativos de gestão pública.</p><p style="text-align: left;">Entre as mudanças culturais ocorridas com a implantação do Plano Diretor da Reforma do Aparelho do Estado (PDRAE), em meados da década de 90 do século passado, inclui-se a transição de um modelo de gestão burocrático para um modelo tecnicista.</p>', 'Julgue o próximo item, no que se às reformas administrativas, à reforma do aparelho do Estado, ao Estado regulador e aos processos participativos de gestão pública.
