INSERT INTO public.questao VALUES (31737, 1968, 3830, '844343', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item seguinte, referente a modelos de gestão pública: o patrimonialista, o burocrático e o gerencial.</p><p style="text-align: left;">Para obter melhorias no funcionamento do setor público, o modelo de gestão gerencial rompeu princípios burocráticos e alterou a estrutura de funcionamento desse setor.</p>', 'Julgue o item seguinte, referente a modelos de gestão pública: o patrimonialista, o burocrático e o gerencial.
