INSERT INTO public.questao VALUES (31739, 1968, 3830, '844462', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de gestão por competências e das tendências na gestão de pessoas no setor público, julgue o item a seguir.</p><p style="text-align: left;">No setor público brasileiro, a gestão de desempenho tem dado mais ênfase na criação de normas e procedimentos a respeito de desempenho dos servidores do que na criação de métodos e técnicas de engajamento e motivação das pessoas em busca de metas e resultados.</p>', 'julgue o item a seguir.
No setor público brasileiro, a gestão de desempenho tem dado mais ênfase na criação de normas e procedimentos a respeito de desempenho dos servidores do que na criação de métodos e técnicas de engajamento e motivação das pessoas em busca de metas e resultados.', true, '2026-02-02 15:17:40.928021', '2026-02-02 15:17:40.928021', 'CERTO', '', false);
INSERT INTO public.questao VALUES (31740, 1968, 3830, '904289', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca das reformas administrativas e da redefinição do papel do Estado brasileiro, julgue o item subsequente.</p><p style="text-align: left;">Com a reforma administrativa de 1967, os componentes da administração pública federal foram separados em integrantes da administração direta e integrantes da administração indireta.</p>', 'julgue o item subsequente.
