INSERT INTO public.questao VALUES (31812, 1968, 3572, '2854563', NULL, 'CEBRASPE', '<p style="text-align: left;">No que tange a aspectos da evolução da administração pública no Brasil e aos modelos de gestão pública, julgue o próximo item.</p><p style="text-align: left;">A adoção de sistemas de mérito como forma de ingresso no serviço público foi uma ação desenvolvida para promover a burocratização na chamada Reforma de 1967.</p>', 'julgue o próximo item.
