INSERT INTO public.questao VALUES (19439, 1968, 3305, '2876378', NULL, 'CEBRASPE', '<p>A respeito da estratégia organizacional, julgue o item subsequente.</p><p>A estratégia baseada em recursos admite que os recursos mais valiosos de uma organização são suas competências essenciais.</p>', 'julgue o item subsequente.
