INSERT INTO public.questao VALUES (19441, 1968, 3305, '2934901', NULL, 'CEBRASPE', '<p style="text-align: left;">No que concerne à gestão de pessoas em organizações públicas, julgue o item a seguir.</p><p style="text-align: left;">Embora a gestão por competências seja uma das principais ferramentas para o levantamento de necessidades e para o planejamento da execução dos programas de treinamento nas organizações, sua aplicação é trabalhosa, o que inviabiliza sua utilização no setor público.</p>', 'julgue o item a seguir.
Embora a gestão por competências seja uma das principais ferramentas para o levantamento de necessidades e para o planejamento da execução dos programas de treinamento nas organizações, sua aplicação é trabalhosa, o que inviabiliza sua utilização no setor público.', true, '2026-01-29 17:44:58.855528', '2026-02-02 15:17:40.928021', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (19442, 1968, 3305, '2983314', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsecutivo, consoante à gestão de pessoas por competências.</p><p style="text-align: left;"><br/>
