INSERT INTO public.questao VALUES (29908, 1994, 3799, '2813466', NULL, 'CEBRASPE', '<p style="text-align:center"><div style="overflow-x: auto; display: inline-block; max-width: 100%; padding: 1px 0"><img src="https://cdn.tecconcursos.com.br/figuras/008e5859-3b4d-4911-8849-a2dbc4b0b446"/></div></p><p style="text-align: left;">Regarding the preceding comic strip and the conversation between the rabbit and the kid, judge the following item.</p><p style="text-align: left;"><br/>
