INSERT INTO public.questao VALUES (19451, 1968, 3305, '3078663', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, a respeito do Estado regulador, dos processos participativos de gestão pública, de accountability e da gestão de pessoas por competências.</p><p style="text-align: left;">Para estabelecer o modelo de gestão por competências apropriado, é necessário considerar as particularidades dos negócios organizacionais e o alinhamento com a orientação estratégica.</p>', 'Julgue o próximo item, a respeito do Estado regulador, dos processos participativos de gestão pública, de accountability e da gestão de pessoas por competências.
Para estabelecer o modelo de gestão por competências apropriado, é necessário considerar as particularidades dos negócios organizacionais e o alinhamento com a orientação estratégica.', true, '2026-01-29 17:44:58.855528', '2026-02-02 15:17:40.928021', 'CERTO', '', false);
INSERT INTO public.questao VALUES (19452, 1968, 3305, '3078665', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, a respeito do Estado regulador, dos processos participativos de gestão pública, de accountability e da gestão de pessoas por competências.</p><p style="text-align: left;">Na gestão por competências, a avaliação de desempenho visa demonstrar aos indivíduos a conformidade com os objetivos da organização, independentemente dos comportamentos adotados para alcançá-los.</p>', 'Julgue o próximo item, a respeito do Estado regulador, dos processos participativos de gestão pública, de accountability e da gestão de pessoas por competências.
