INSERT INTO public.questao VALUES (32353, 1969, 3837, '844375', NULL, 'CEBRASPE', '<p style="text-align: left;">A propósito de avaliações de políticas públicas e programas governamentais, julgue o item.</p><p style="text-align: left;">A atividade de monitoramento constitui um processo contínuo que retroalimenta o ciclo de ajustes de uma política.</p>', 'julgue o item.
