INSERT INTO public.questao VALUES (32697, 1971, 3574, '69659', NULL, 'CEBRASPE', '<p>Julgue o próximo item, a respeito da organização administrativa da União, considerando a administração direta e indireta.<br/></p><p style="text-align: left;">O Serviço Nacional do Comércio (SENAC), como serviço social autônomo sem fins lucrativos, é exemplo de empresa pública que desempenha atividade de caráter econômico ou de prestação de serviços públicos.</p>', 'Julgue o próximo item, a respeito da organização administrativa da União, considerando a administração direta e indireta.
O Serviço Nacional do Comércio (SENAC), como serviço social autônomo sem fins lucrativos, é exemplo de empresa pública que desempenha atividade de caráter econômico ou de prestação de serviços públicos.', true, '2026-02-02 15:17:40.928021', '2026-02-02 15:17:40.928021', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (32699, 1971, 3574, '1560888', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca da administração pública e dos servidores públicos, julgue o item a seguir.</p><p style="text-align: left;">Entidades paraestatais são pessoas jurídicas de direito privado que colaboram com o Estado no desempenho de atividades não lucrativas; elas não integram a estrutura da administração pública.</p>', 'julgue o item a seguir.
