INSERT INTO public.questao VALUES (37149, 2000, 3997, '3315008', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, referente ao Microsoft Office 365, a redes de computadores, à segurança da informação e à inteligência artificial.</p><p style="text-align: left;">No Word do ambiente Microsoft Office 365, texto separado por tabulações pode ser convertido em tabela, para isso, basta selecionar o texto e clicar na opção Tabela, encontrada na guia Inserir.</p>', 'Julgue o item a seguir, referente ao Microsoft Office 365, a redes de computadores, à segurança da informação e à inteligência artificial.
