INSERT INTO public.questao VALUES (37152, 2000, 3997, '3439334', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, referente ao emprego de <em>softwares</em> de editoração eletrônica e de imagens vetoriais pelo profissional da comunicação visual.</p><p style="text-align: left;"><em>Softwares </em>como o Microsoft Word são usados prioritariamente para a edição de textos, porém também oferecem recursos de formatação, diagramação e inserção de elementos gráficos, como tabelas e imagens.</p>', 'Julgue o item a seguir, referente ao emprego de 
