INSERT INTO public.questao VALUES (37183, 2000, 3997, '2459875', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação a conceitos gerais de informática básica, julgue o item a seguir.</p><p style="text-align: left;">O programa Microsoft Word carece de símbolos e notas musicais, pois não oferece a opção de digitação de caracteres que não estejam no teclado do computador.</p>', 'julgue o item a seguir.
