INSERT INTO public.questao VALUES (37186, 2000, 3997, '2503578', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação a segurança na Internet, periféricos de computadores, computação em nuvem e editores de texto e planilhas eletrônicas, julgue o seguinte item.</p><p style="text-align: left;"><br/>
