INSERT INTO public.questao VALUES (37188, 2000, 3997, '2588971', NULL, 'CEBRASPE', '<p style="text-align: left;">Certo analista fazendário recebeu arquivo em formato pdf e deverá aproveitar parte das informações e dos dados constantes do arquivo para elaborar parecer técnico.</p><p style="text-align: left;"><br/>
