INSERT INTO public.questao VALUES (37189, 2000, 3997, '2639047', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, relativos ao Microsoft Word e ao Microsoft Excel avançado.</p><p style="text-align: left;">O Microsoft Word permite que se utilizem modelos personalizados da Microsoft, mas impede a criação de modelos a partir de documentos existentes.</p>', 'Julgue o item a seguir, relativos ao Microsoft Word e ao Microsoft Excel avançado.
