INSERT INTO public.questao VALUES (37219, 2000, 3998, '1390362', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item seguinte, a respeito dos conceitos de planilhas e SQL.</p><p style="text-align: left;">Os dados em uma planilha podem ser classificados: se os nomes forem classificados em ordem crescente, então eles serão classificados de A para Z.</p>', 'Julgue o item seguinte, a respeito dos conceitos de planilhas e SQL.
