INSERT INTO public.questao VALUES (37236, 2000, 3999, '3501712', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, relativos ao ambiente Windows, ao Microsoft Office e a redes de computadores.</p><p style="text-align: left;">Ao se utilizar a função <span style="">SOMASE</span> do Excel 2019, caso haja um critério que inclua símbolos lógicos ou matemáticos, ele deve estar entre aspas duplas.</p>', 'Julgue o próximo item, relativos ao ambiente Windows, ao Microsoft Office e a redes de computadores.
