INSERT INTO public.questao VALUES (37317, 2000, 4002, '2531766', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação aos conceitos básicos e ao uso da Internet bem como às ferramentas Google utilizadas na área da educação, julgue o item a seguir.</p><p style="text-align: left;"><br/>
