INSERT INTO public.questao VALUES (37245, 2000, 3999, '2847628', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de edição de textos, planilhas e apresentações no Microsoft Office 365 e no LibreOffice, julgue o item a seguir.</p><p style="text-align: left;">No Microsoft Excel, o operador comercial — &amp; — é um operador de concatenação de texto; ele permite conectar ou associar dois valores para produzir um valor de texto contínuo.</p>', 'julgue o item a seguir.
