INSERT INTO public.questao VALUES (37249, 2000, 3999, '3038867', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação ao Microsoft Excel, julgue o seguinte item.</p><p style="text-align: left;"><br/>
