INSERT INTO public.questao VALUES (38109, 2002, 4028, '2036010', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere a conceitos de malware e detectores de intrusão, julgue o item seguinte.</p><p style="text-align: left;">Malwares utilizam um protocolo de monitoramento de ativos financeiros com o objetivo de trazer informações para os usuários infectados.</p>', 'julgue o item seguinte.
