INSERT INTO public.questao VALUES (37328, 2000, 4003, '2783413', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de intranet, navegadores de Internet, programas de correio eletrônico e sítios de busca e pesquisa na Internet, julgue o próximo item.</p><p style="text-align: left;"><em>Intranet </em>é uma rede corporativa privada, cujo acesso é gerenciado por uma organização, de modo que, para acessá-la fora da empresa, é necessário utilizar <em>softwares</em> específicos, como VPN (<em>virtual private network).</em></p>', 'julgue o próximo item.
