INSERT INTO public.questao VALUES (37330, 2000, 4003, '2981479', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de redes de computadores e de ferramentas disponíveis para comunicação na Internet, julgue o item que se segue.</p><p style="text-align: left;"><br/>
