INSERT INTO public.questao VALUES (37331, 2000, 4003, '3142419', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item que se segue, a respeito de Internet e <em>intranet.</em></p><p style="text-align: left;">A <em>intranet</em>, ao contrário da Internet, é uma área de uso exclusivo de seus proprietários, ou seja, é uma plataforma de comunicação que pertence a uma única organização e serve como infraestrutura para compartilhamento de informações, arquivos, aplicações, serviços e recursos em seu ambiente interno de trabalho.</p>', 'Julgue o item que se segue, a respeito de Internet e 
intranet.
