INSERT INTO public.questao VALUES (37332, 2000, 4003, '2341676', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando uma lista dos diretórios comuns no SO Linux que estão diretamente sob o diretório <span style="">root (/),</span> julgue o item seguinte.</p><p style="text-align: left;">O que caracteriza a Intranet é a privacidade de dados, uma vez que é acessível somente por meio de senha e todo seu conteúdo é armazenado de forma criptografada.</p>', 'julgue o item seguinte.
