INSERT INTO public.questao VALUES (37334, 2000, 4003, '2520662', NULL, 'CEBRASPE', '<p style="text-align: left;">Após uma diligência, certo auditor fiscal deverá criar relatório reportando o caso e, em seguida, encaminhar o relatório para o órgão responsável, junto com a documentação comprobatória.</p><p style="text-align: left;"><br/>
