INSERT INTO public.questao VALUES (37355, 2000, 4005, '3544378', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito do Google Chrome, de redes sociais, de modelos de computação em nuvem e do gerenciamento de pastas e arquivos no Windows, julgue o item a seguir.</p><p style="text-align: left;">Com o Google Chrome, é possível instalar extensões como tradutores ou bloqueadores de anúncios e sincronizar os favoritos do usuário em qualquer dispositivo com uma conta Google.</p>', 'julgue o item a seguir.
