INSERT INTO public.questao VALUES (37356, 2000, 4005, '2779500', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação a conceitos básicos de Internet e programas utilizados para navegação, pesquisa ou comunicação, julgue os item que se segue.</p><p style="text-align: left;"><br/>
