INSERT INTO public.questao VALUES (37382, 2000, 4005, '551459', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, acerca de noções básicas de informática.</p><p style="text-align: left;">No Google Chrome, a opção <span style="">Históricos – Limpar Dados de Navegação</span> possibilita apagar os endereços de páginas visitadas e, também, remover lista de arquivos baixados (<span style=""><em>downloads</em></span>) da Internet pelo usuário.</p>', 'Julgue o item a seguir, acerca de noções básicas de informática.
