INSERT INTO public.questao VALUES (37383, 2000, 4005, '552201', NULL, 'CEBRASPE', '<p style="text-align: left;"><span style="text-align: left;">Julgue o próximo item, relativo ao sistema operacional Linux, ao programa Microsoft Excel 2013 e ao programa de navegação Google Chrome.</span></p><p style="text-align: left;">Ainda que o usuário exclua o histórico de downloads do Google Chrome, os arquivos contidos nesse histórico não são removidos do computador.</p>', 'Julgue o próximo item, relativo ao sistema operacional Linux, ao programa Microsoft Excel 2013 e ao programa de navegação Google Chrome.
