INSERT INTO public.questao VALUES (37384, 2000, 4006, '3258555', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação a sistemas operacionais, programas do Microsoft Office, navegadores e Microsoft Outlook, julgue os tem a seguir.</p><p style="text-align: left;">Além de limpar o histórico de navegação e o histórico de<em> downloads</em>, o modo <span style="">InPrivate</span> do navegador Microsoft Edge apaga os cookies, os arquivos baixados e os sites selecionados como favoritos durante uma sessão de navegação realizada em modo InPrivate.</p>', 'Além de limpar o histórico de navegação e o histórico de<em> downloads</em>, o modo <span style="">InPrivate</span> do navegador Microsoft Edge apaga os cookies, os arquivos baixados e os sites selecionados como favoritos durante uma sessão de navegação realizada em modo InPrivate.</p>', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (37385, 2000, 4006, '3344794', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere a redes de computadores e ao uso transparente e imparcial de inteligência artificial (IA) no serviço público, julgue o item subsequente.</p><p style="text-align: left;">O Microsoft Edge permite que se ajuste o nível de prevenção de rastreamento para equilibrar privacidade e personalização, sendo o nível básico recomendado para a maioria dos usuários.</p>', 'julgue o item subsequente.
