INSERT INTO public.questao VALUES (37386, 2000, 4006, '3422372', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de navegadores de Internet, julgue o item a seguir.</p><p style="text-align: left;">O Microsoft Edge oferece um modo Internet Explorer (IE) para acessar <em>sites </em>legados projetados especificamente para o IE.</p>', 'julgue o item a seguir.
