INSERT INTO public.questao VALUES (37390, 2000, 4006, '2975069', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação a Microsoft Edge e Google Chrome, julgue o seguinte item.</p><p style="text-align: left;"><br/>
