INSERT INTO public.questao VALUES (37391, 2000, 4006, '2988073', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsequente, relativo a Microsoft Edge e Google Chrome.</p><p style="text-align: left;"><br/>
