INSERT INTO public.questao VALUES (37404, 2000, 4008, '3661325', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsequente, relativos ao sistema operacional Windows, à computação em nuvem e aos conceitos de Internet e<em> intranet</em>.</p><p style="text-align: left;">Computação em nuvem é uma plataforma ou estilo de computação que permite acesso remoto a recursos compartilhados de forma dinâmica e escalável, geralmente via Internet.</p>', 'Julgue o item subsequente, relativos ao sistema operacional Windows, à computação em nuvem e aos conceitos de Internet e
