INSERT INTO public.questao VALUES (37438, 2000, 4008, '1739271', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação a computação em nuvem, julgue o item a seguir.</p><p style="text-align: left;">O provisionamento para aumento de recursos como memória ram e armazenamento é uma característica disponibilizada em um ambiente de PaaS <em>(Platform as a Service).</em></p>', 'julgue o item a seguir.
