INSERT INTO public.questao VALUES (37447, 2000, 4008, '687319', NULL, 'CEBRASPE', '<p>Julgue o item a respeito de redes de computadores e de<em> cloud computing</em>.</p><p>Entre os modelos de computação em nuvem, o PaaS (Plataforma como um serviço) é o mais indicado para o desenvolvimento de soluções informatizadas.</p>', 'Julgue o item a respeito de redes de computadores e de
