INSERT INTO public.questao VALUES (37452, 2000, 4009, '3312893', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, referente ao Microsoft Office 365, aredes de computadores, à segurança da informação e à inteligência artificial.</p><p style="text-align: left;">Ao utilizar o OneDrive, os arquivos são armazenados em nuvem, o que permite acesso remoto e sincronização entre dispositivos, como computadores,<em> tablets</em> e celulares.</p>', 'Julgue o item a seguir, referente ao Microsoft Office 365, aredes de computadores, à segurança da informação e à inteligência artificial.
