INSERT INTO public.questao VALUES (37480, 2000, 4015, '3501729', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca da organização e do gerenciamento de arquivos, de tipos de <em>malware</em> e do armazenamento de dados em nuvem, julgue o item subsequente.</p><p style="text-align: left;"><em>Ransomware</em> é um tipo de <em>malware</em> que não pode ser propagado por <em>phishing,</em> mas bloqueia o acesso ao sistema ou criptografa os arquivos da vítima, sendo exigido um pagamento de resgate para que o acesso seja restaurado.</p>', 'julgue o item subsequente.
