INSERT INTO public.questao VALUES (37481, 2000, 4015, '3501841', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação a vírus e antivírus, julgue o item a seguir.</p><p style="text-align: left;">Um vírus multipartite utiliza diversos métodos para infectar o computador, começando pela memória e se espalhando pelos demais componentes.</p>', 'julgue o item a seguir.
