INSERT INTO public.questao VALUES (37483, 2000, 4015, '3596729', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, relativo a conceitos de informática.</p><p style="text-align: left;">É seguro conectar qualquer<em> pendrive</em> ao computador, desde que ele seja aberto inicialmente no modo somente leitura, pois vírus não conseguem se propagar sem permissão explícita do usuário.</p>', 'Julgue o próximo item, relativo a conceitos de informática.
