INSERT INTO public.questao VALUES (37487, 2000, 4015, '2975084', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item que se segue, a respeito de segurança da informação.</p><p style="text-align: left;">O <em>trojan</em> é projetado para espionar o dono do dispositivo, que não autorizou a sua instalação e não sabe que tal código espião está instalado em seu equipamento, permitindo que o agente malicioso receba informações confidenciais coletadas.</p>', 'Julgue o item que se segue, a respeito de segurança da informação.
