INSERT INTO public.questao VALUES (37488, 2000, 4015, '2979912', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, referente a segurança da informação, organização e gerenciamento de informações, arquivos, pastas e programas.</p><p style="text-align: left;"><em>Ransomware</em> é um tipo de malware (código malicioso) que infecta computadores e dispositivos, criptografando os arquivos do sistema ou bloqueando o acesso do usuário aos próprios dados.</p>', 'Julgue o item a seguir, referente a segurança da informação, organização e gerenciamento de informações, arquivos, pastas e programas.
