INSERT INTO public.questao VALUES (37489, 2000, 4015, '2988078', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, a respeito de segurança da informação.</p><p style="text-align: left;"><em>Keylogger</em> é um tipo de <em>spyware </em>projetado para monitorar as atividades de um sistema por meio da captura e do armazenamento das teclas digitadas.</p>', 'Julgue o próximo item, a respeito de segurança da informação.
