INSERT INTO public.questao VALUES (37530, 2000, 4015, '1554636', NULL, 'CEBRASPE', '<p style="text-align: left;">Ao redigir um ofício destinado a uma provedora de Internet, um delegado colocou as seguintes informações a respeito de uma possível captura de dados não autorizada pelo usuário de um sistema.</p><div style="overflow-x: auto; display: block"><table style="margin: 0px auto;"><tbody><tr><td><p>URL correta de<br/>
