INSERT INTO public.questao VALUES (37549, 2000, 4015, '354246', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação a informática, julgue o item que se segue.</p><p style="text-align: left;">A infecção de um computador por vírus enviado via correio eletrônico pode se dar quando se abre arquivo infectado que porventura esteja anexado à mensagem eletrônica recebida.</p>', 'julgue o item que se segue.
