INSERT INTO public.questao VALUES (37561, 2000, 4016, '3664078', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere a armazenamento de dados na nuvem, pragas virtuais e <em>firewall</em>, julgue o item subsequente.</p><p style="text-align: left;">Um <em>firewall </em>é um sistema de controle de tráfego digital que garante mais segurança a redes e dispositivos, funcionando como primeira linha de defesa contra acessos indesejados.</p>', 'julgue o item subsequente.
