INSERT INTO public.questao VALUES (37569, 2000, 4016, '1718312', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, acerca de conhecimentos de informática.</p><p style="text-align: left;">Em um<em> firewall </em>corretamente instalado e configurado, toda troca de dados entre a rede interna e a rede externa de uma organização deve passar por ele.</p>', 'Julgue o próximo item, acerca de conhecimentos de informática.
