INSERT INTO public.questao VALUES (37594, 2000, 4017, '1740438', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item seguinte, relativos a organização de arquivos e suas premissas de segurança.</p><p style="text-align: left;">A heurística é um dos métodos de detecção das ferramentas <em>antimalware</em> — como antivírus, <em>antirootkit</em> e <em>antispyware</em> — que se baseiam nas estruturas, instruções e características que o código malicioso possui para identificá-lo.</p>', 'Julgue o item seguinte, relativos a organização de arquivos e suas premissas de segurança.
