INSERT INTO public.questao VALUES (37597, 2000, 4017, '354484', NULL, 'CEBRASPE', '<p style="text-align: left;">O próximo item, que aborda procedimentos de informática e conceitos de Internet e<em> intranet</em>, apresenta uma situação hipotética, seguida de uma assertiva a ser julgada.<br/></p><p style="text-align: left;">Ao iniciar seu dia de trabalho, Daniel se deparou com inúmeros aplicativos abertos em seu computador de trabalho, o que deixava sua máquina lenta e sujeita a travamentos frequentes. Ele constatou, ainda, que somente um desses aplicativos era necessário para a execução de suas atividades. Nessa situação, para melhorar o desempenho do seu computador, Daniel deve utilizar um aplicativo de antivírus instalado localmente, para eliminar os aplicativos que estiverem consumindo recursos além do normal.</p>', 'Ao iniciar seu dia de trabalho, Daniel se deparou com inúmeros aplicativos abertos em seu computador de trabalho, o que deixava sua máquina lenta e sujeita a travamentos frequentes. Ele constatou, ainda, que somente um desses aplicativos era necessário para a execução de suas atividades. Nessa situação, para melhorar o desempenho do seu computador, Daniel deve utilizar um aplicativo de antivírus instalado localmente, para eliminar os aplicativos que estiverem consumindo recursos além do normal.</p>', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (37642, 1972, 4020, '1509650', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação aos conceitos de análise de dados e informações, julgue o item a seguir.</p><p style="text-align: left;">O conceito de inteligência está relacionado à capacidade de julgamento, ou seja, o ser humano usa o seu conhecimento para tomar a melhor decisão em uma situação real.</p>', 'julgue o item a seguir.
