INSERT INTO public.questao VALUES (37641, 1972, 4020, '1509649', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação aos conceitos de análise de dados e informações, julgue o item a seguir.</p><p style="text-align: left;"><br/>
