INSERT INTO public.questao VALUES (37666, 1972, 4021, '1936883', NULL, 'CEBRASPE', '<p style="text-align: left;">Quanto a dados estruturados e não estruturados, julgue o item subsecutivo.</p><p style="text-align: left;"><br/>
