INSERT INTO public.questao VALUES (37656, 1972, 4021, '3041186', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item que se segue, a respeito de qualidade de dados.</p><p style="text-align: left;">A limpeza de dados consiste em remover ou modificar dados corretos, completos, relevantes ou que estão formatados incorretamente.</p>', 'Julgue o item que se segue, a respeito de qualidade de dados.
