INSERT INTO public.questao VALUES (37657, 1972, 4021, '3076514', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de Big Data, julgue o próximo item.</p><p style="text-align: left;">Assim como os dados estruturados, os dados não estruturados também podem ser armazenados em bancos de dados relacionais.</p>', 'julgue o próximo item.
