INSERT INTO public.questao VALUES (37658, 1972, 4021, '3104445', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, relativo a dados e bancos de dados.</p><p style="text-align: left;"><br/>
