INSERT INTO public.questao VALUES (37659, 1972, 4021, '3172503', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, relativos a dado, informação, conhecimento e inteligência.</p><p style="text-align: left;">É possível que grandes dados numéricos ou textuais não sejam estruturados em razão da ineficiência em modelá-los como uma tabela.</p>', 'Julgue o próximo item, relativos a dado, informação, conhecimento e inteligência.
