INSERT INTO public.questao VALUES (37675, 1972, 4022, '3422062', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de gestão da informação, julgue o item a seguir.</p><p style="text-align: left;">Informações classificadas como confidenciais são acessadas somente por usuários da organização; o seu acesso por parceiros e clientes, por exemplo, compromete a segurança dos dados.</p>', 'julgue o item a seguir.
