INSERT INTO public.questao VALUES (37676, 1972, 4022, '2818596', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de dado, informação, conhecimento e inteligência, julgue o item a seguir.</p><p style="text-align: left;"><br/>
