INSERT INTO public.questao VALUES (37712, 1972, 4023, '2798080', NULL, 'CEBRASPE', '<p style="text-align: left;">Com base em obtenção, limpeza e pré-processamento de dados, julgue o próximo item.</p><p style="text-align: left;">A análise descritiva tem como objetivo responder à pergunta ‘o que aconteceu?’, ao passo que a análise diagnóstica visa responder à questão ‘por que isso aconteceu?’.</p>', 'julgue o próximo item.
