INSERT INTO public.questao VALUES (37713, 1972, 4023, '2798149', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de ontologia, julgue o próximo item.</p><p style="text-align: left;">A representação formal de ontologias é utilizada para que estas sejam consumidas por computadores, enquanto a representação gráfica é utilizada para compreensão humana.</p>', 'julgue o próximo item.
