INSERT INTO public.questao VALUES (37714, 1972, 4023, '2798150', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de ontologia, julgue o próximo item.</p><p style="text-align: left;">Ontologias podem ser entendidas como aplicações criadas para simular a ação de especialistas humanos, com o propósito de solucionar problemas específicos em um dado domínio.</p>', 'julgue o próximo item.
