INSERT INTO public.questao VALUES (37715, 1972, 4023, '2798151', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de ontologia, julgue o próximo item.</p><p style="text-align: left;">Na ontologia, o conjunto de axiomas do domínio é aquele que serve para modelar restrições e regras inerentes às instâncias.</p>', 'julgue o próximo item.
