INSERT INTO public.questao VALUES (37716, 1972, 4023, '2854398', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação à inteligência artificial e a suas técnicas, bem como aos sistemas de recomendação, julgue o item subsequente.</p><p style="text-align: left;"><br/>
