INSERT INTO public.questao VALUES (37717, 1972, 4023, '2854410', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de visão computacional, julgue o item seguinte.</p><p style="text-align: left;">A visão computacional usa algoritmos para alterar imagens, no que diz respeito, por exemplo, a nitidez, suavização, filtragem ou aprimoramento.</p>', 'julgue o item seguinte.
