INSERT INTO public.questao VALUES (37724, 1972, 4023, '2993093', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação a tecnologias de IA e aprendizado de máquina, julgue o item que se segue.</p><p style="text-align: left;"><br/>
