INSERT INTO public.questao VALUES (37726, 1972, 4023, '3041837', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação à privacidade em governança e ética de inteligência artificial, julgue o item seguinte.</p><p style="text-align: left;"><br/>
