INSERT INTO public.questao VALUES (37727, 1972, 4023, '3076546', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação à inteligência artificial (IA), julgue o item a seguir.</p><p style="text-align: left;">As redes adversárias generativas utilizam a rede geradora para produzir dados falsos aleatoriamente e a discriminadora para identificar esses dados falsos.</p>', 'julgue o item a seguir.
