INSERT INTO public.questao VALUES (37729, 1972, 4023, '3076779', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação à inteligência artificial (IA), julgue o item a seguir.</p><p style="text-align: left;">Os modelos de difusão são focados na classificação de pontos de dados para determinar a relação entre fatores conhecidos e desconhecidos.</p>', 'julgue o item a seguir.
