INSERT INTO public.questao VALUES (37894, 2001, 4026, '2640736', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de armazenamento orientado a objetos (<em>object store</em>) com o serviço S3, julgue o item a seguir.</p><p style="text-align: left;">Arquivos armazenados em diferentes localidades de um mesmo país ou em países diferentes podem ser replicados a partir da utilização desse serviço.</p>', 'julgue o item a seguir.
