INSERT INTO public.questao VALUES (37900, 2001, 4026, '2642320', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando o ambiente <em>multicloud </em>híbrido associado às melhores práticas de gestão de informações, julgue o item seguinte.</p><p style="text-align: left;">O Google ApiGee é fornecido nas modalidades PaaS e IaaS.</p>', 'julgue o item seguinte.
