INSERT INTO public.questao VALUES (37949, 2001, 4026, '2265659', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de virtualização de servidores e computação em nuvem, julgue o item que se segue.</p><p style="text-align: left;"><br/>
