INSERT INTO public.questao VALUES (37950, 2001, 4026, '2265660', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de virtualização de servidores e computação em nuvem, julgue o item que se segue.</p><p style="text-align: left;">PaaS é o tipo de infraestrutura indicada para desenvolvimento de aplicações que rodam em nuvem, pois oferecem recursos indicados para essa situação.</p>', 'julgue o item que se segue.
