INSERT INTO public.questao VALUES (37951, 2001, 4026, '2266018', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando a figura a seguir, julgue o próximo item, acerca dos conceitos de DevOps.</p><p style="text-align:center"><div style="overflow-x: auto; display: inline-block; max-width: 100%; padding: 1px 0"><img src="https://cdn.tecconcursos.com.br/figuras/ac5a61e9-4168-40a0-97d6-98c6471d8e7f"/></div></p><p style="text-align: left;">Um <em>serverless </em>é definido como um modelo operacional cujos princípios incluem a ausência de infraestrutura para gerenciar e o dimensionamento automático por unidade de consumo.</p>', 'julgue o próximo item, acerca dos conceitos de DevOps.
Um 
serverless 
é definido como um modelo operacional cujos princípios incluem a ausência de infraestrutura para gerenciar e o dimensionamento automático por unidade de consumo.', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'CERTO', 'https://cdn.tecconcursos.com.br/figuras/ac5a61e9-4168-40a0-97d6-98c6471d8e7f', false);
INSERT INTO public.questao VALUES (38041, 2002, 4027, '2216645', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de confiabilidade, integridade e disponibilidade em segurança da informação, julgue o item subsequente.</p><p style="text-align: left;"><br/>
