INSERT INTO public.questao VALUES (37967, 2001, 4026, '595388', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de cloud computing, julgue o item.</p><p style="text-align: left;">Um dos exemplos de utilização da computação em nuvem é a virtualização, na qual duas máquinas virtuais são implementadas em um mesmo equipamento físico.</p>', 'julgue o item.
