INSERT INTO public.questao VALUES (37968, 2001, 4026, '595389', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de cloud computing, julgue o item.</p><p style="text-align: left;">Uma das premissas da computação em nuvem é que a empresa contratante seja informada sobre a localização geográfica exata de armazenamento dos seus dados.</p>', 'julgue o item.
