INSERT INTO public.questao VALUES (37969, 2001, 4026, '595390', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de cloud computing, julgue o item.</p><p style="text-align: left;">A utilização da computação em nuvem é desaconselhada para novos negócios, tendo em vista que a opção por essa tecnologia demanda grande investimento inicial.</p>', 'julgue o item.
