INSERT INTO public.questao VALUES (37972, 2001, 4026, '626261', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o seguinte item, referente a conceitos de computação em nuvem.</p><p style="text-align: left;"><br/>
