INSERT INTO public.questao VALUES (38043, 2002, 4027, '2216706', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de confiabilidade, integridade e disponibilidade em segurança da informação, julgue o item subsequente.</p><p style="text-align: left;"><br/>
Habilitar <em>logs</em> de sistema e de controle de acesso, criptografia de dados de um disco e sistemas de antivírus atualizados são medidas que garantem a integridade.</p>', 'julgue o item subsequente.
