INSERT INTO public.questao VALUES (38044, 2002, 4027, '2216708', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de confiabilidade, integridade e disponibilidade em segurança da informação, julgue o item subsequente.</p><p style="text-align: left;"><br/>
