INSERT INTO public.questao VALUES (38045, 2002, 4027, '2216709', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de confiabilidade, integridade e disponibilidade em segurança da informação, julgue o item subsequente.</p><p style="text-align: left;"><br/>
Oportunidade, continuidade e robustez são características da confiabilidade.</p>', 'julgue o item subsequente.
Oportunidade, continuidade e robustez são características da confiabilidade.', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (38046, 2002, 4027, '2216721', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de ameaça, vulnerabilidade e impacto em segurança da informação, julgue o item que se segue.</p><p style="text-align: left;">Vulnerabilidade é o grau de suscetibilidade de um objeto a uma ameaça.</p>', 'julgue o item que se segue.
Vulnerabilidade é o grau de suscetibilidade de um objeto a uma ameaça.', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'CERTO', '', false);
INSERT INTO public.questao VALUES (38047, 2002, 4027, '2216909', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação à segurança em redes de computadores, julgue o item subsequente.</p><p style="text-align: left;">Em segurança da informação, o conceito de disponibilidade refere-se à preservação da integridade dos dados disponibilizados aos usuários, a fim de evitar alterações indevidas.</p>', 'julgue o item subsequente.
Em segurança da informação, o conceito de disponibilidade refere-se à preservação da integridade dos dados disponibilizados aos usuários, a fim de evitar alterações indevidas.', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (38048, 2002, 4027, '2218192', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, a respeito de otimização de desempenho em servidores e de política de <em>backup</em>.</p><p style="text-align: left;"><br/>
Um componente é redundante quando fornece criptografia e segurança adequadas ao banco de dados de <em>back-end</em> ou quando armazena o sistema operacional por meio do armazenamento dos dados.</p>', 'Julgue o item a seguir, a respeito de otimização de desempenho em servidores e de política de 
backup
