INSERT INTO public.questao VALUES (38082, 2002, 4028, '2781248', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de <em>keyloggers</em> e suas características, julgue o item subsequente.</p><p style="text-align: left;">De maneira geral, <em>keyloggers</em> são códigos maliciosos usados para capturar informações à medida que existe alguma interação do usuário com o teclado; esses códigos podem estar inseridos em software ou até mesmo<em> hardware</em> específico.</p>', 'julgue o item subsequente.
