INSERT INTO public.questao VALUES (38084, 2002, 4028, '2783913', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item que se segue, relativo à segurança de rede de computadores e <em>spywares.</em></p><p style="text-align: left;">O <em>spyware </em>conhecido como Predator é capaz de realizar uma forma de<em> cyberataque </em>em que o criminoso age como um intermediário entre a vítima e o sítio de um banco ou mesmo de outros usuários.</p>', 'Julgue o item que se segue, relativo à segurança de rede de computadores e 
