INSERT INTO public.questao VALUES (38092, 2002, 4028, '2847646', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, referente a vírus, worms, pragas virtuais e aplicativos de segurança.</p><p style="text-align: left;"><em>Hijacker </em>é um tipo de <em>malware </em>que invade o computador e criptografa os dados de forma que o usuário perde o acesso aos próprios dados.</p>', 'Julgue o item a seguir, referente a vírus, worms, pragas virtuais e aplicativos de segurança.
