INSERT INTO public.questao VALUES (38113, 2002, 4028, '2218130', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação aos tipos de <em>malwares</em>, julgue o item que se segue.</p><p style="text-align: left;"><br/>
