INSERT INTO public.questao VALUES (38114, 2002, 4028, '2613458', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, a respeito de ataques a redes de computadores, <em>softwares </em>maliciosos e vulnerabilidades em aplicações.</p><p style="text-align: left;"><em>Malware </em>é qualquer <em>software </em>intencionalmente criado para causar danos a um computador, servidor, cliente ou a uma rede de computadores.</p>', 'Julgue o item a seguir, a respeito de ataques a redes de computadores, 
