INSERT INTO public.questao VALUES (38118, 2002, 4028, '1739693', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação a noções de vírus, valor da informação, procedimentos de<em> backup</em> e aplicativos de segurança, julgue o item a seguir.</p><p style="text-align: left;">Vírus é um pequeno programa de computador que propositalmente se replica e não depende de um usuário para se espalhar, uma vez que, quando ativado, se espalha automaticamente.</p>', 'julgue o item a seguir.
Vírus é um pequeno programa de computador que propositalmente se replica e não depende de um usuário para se espalhar, uma vez que, quando ativado, se espalha automaticamente.', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (38119, 2002, 4028, '1393694', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de <em>software</em> malicioso e segurança da infraestrutura de TI, julgue o item subsecutivo.</p><p style="text-align: left;">Contêineres têm sido usados como mecanismo de implantação de <em>malware</em> na infraestrutura em nuvem, sendo o H2Miner um exemplo de<em> botnet</em> capaz de utilizar esse tipo de mecanismo.</p>', 'julgue o item subsecutivo.
