INSERT INTO public.questao VALUES (38161, 2002, 4030, '2847651', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o próximo item, a respeito de procedimentos de backup e armazenamento de dados na nuvem.</p><p style="text-align: left;">O tipo de<em> backup </em>de dados que mais consome espaço de armazenamento no computador é o<em> backup</em> incremental.</p>', 'Julgue o próximo item, a respeito de procedimentos de backup e armazenamento de dados na nuvem.
