INSERT INTO public.questao VALUES (38184, 2002, 4030, '1971118', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de backup e recuperação de dados, julgue o item subsecutivo.</p><p style="text-align: left;">O método de <em>backup</em> 3-2-1 consiste em manter três cópias dos dados (a original e dois<em> backups</em>), utilizar dois tipos diferentes de mídia e deixar uma cópia remota.</p>', 'julgue o item subsecutivo.
