INSERT INTO public.questao VALUES (38185, 2002, 4030, '1980646', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere a becape, julgue o item subsecutivo.</p><p style="text-align: left;">Uma política de becape deve abordar quais os dados a serem armazenados, a frequência de execução e quem será responsável pelo acompanhamento dos processos de becape.</p>', 'julgue o item subsecutivo.
