INSERT INTO public.questao VALUES (38186, 2002, 4030, '1980647', NULL, 'CEBRASPE', '<p style="text-align: left;">No que se refere a becape, julgue o item subsecutivo.</p><p style="text-align: left;">Ao optar por becape na nuvem, a organização deve atentar para a armazenagem, que envolve o tempo para restauração em caso de incidente.</p>', 'julgue o item subsecutivo.
