INSERT INTO public.questao VALUES (38190, 2002, 4030, '2218189', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item a seguir, a respeito de otimização de desempenho em servidores e de política de <em>backup</em>.</p><p style="text-align: left;"><br/>
