.', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'CERTO', '', false);
INSERT INTO public.questao VALUES (38290, 2002, 4031, '389763', NULL, 'CEBRASPE', '<p style="text-align: left;">
	Julgue o item seguinte, relativo à segurança em Linux.</p><p style="text-align: left;">
	A ferramenta IPTables controla o módulo Netfilter do<em> kernel</em> Linux, módulo que, por sua vez, controla as funções NAT,<em> firewall </em>e<em> log </em>do sistema.</p>', 'Julgue o item seguinte, relativo à segurança em Linux.
