do sistema.', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'CERTO', '', false);
INSERT INTO public.questao VALUES (38291, 2002, 4031, '389864', NULL, 'CEBRASPE', '<p style="text-align: left;">
	Julgue o próximo item, a respeito de elementos utilizados para proteção e segurança de redes de computadores.</p><p style="text-align: left;">
