INSERT INTO public.questao VALUES (38294, 2002, 4031, '558842', NULL, 'CEBRASPE', '<p style="text-align: left;">
		Ferramentas de <em>firewall </em>são amplamente utilizadas em redes de computadores, de maneira a permitir ou negar determinado fluxo de pacotes. Com relação a <em>firewall </em>convencional de rede, julgue o item subsecutivo.</p><p style="text-align: left;">
		Ao verificar a porta de origem e de destino de um pacote do tipo UDP, o <em>firewall </em>fragmenta automaticamente pacotes UDP com a porta de origem 01 e de destino como 02, já que são portas utilizadas para controle de fluxo de pacotes de tempo real.</p>', 'julgue o item subsecutivo.
		Ao verificar a porta de origem e de destino de um pacote do tipo UDP, o 
firewall 
fragmenta automaticamente pacotes UDP com a porta de origem 01 e de destino como 02, já que são portas utilizadas para controle de fluxo de pacotes de tempo real.', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (38295, 2002, 4031, '558843', NULL, 'CEBRASPE', '<p style="text-align: left;">
		Ferramentas de <em>firewall </em>são amplamente utilizadas em redes de computadores, de maneira a permitir ou negar determinado fluxo de pacotes. Com relação a <em>firewall </em>convencional de rede, julgue o item subsecutivo.</p><p>
			Um <em>firewall </em>é capaz de verificar tanto o endereço IP de origem quanto o endereço IP de destino em um pacote de rede.</p>', 'julgue o item subsecutivo.
			Um 
firewall 
é capaz de verificar tanto o endereço IP de origem quanto o endereço IP de destino em um pacote de rede.', true, '2026-02-02 18:38:45.483219', '2026-02-02 18:38:45.483219', 'CERTO', '', false);
