INSERT INTO public.questao VALUES (39763, 2006, 4084, '685190', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando que a análise de uma amostra de minério de chumbo tenha apresentado os seguintes resultados percentuais (%): 8,10; 8,32; 8,12; 8,22; 7,99; 8,31, julgue o item a seguir, relativo a esses dados.</p><p style="text-align: left;">A variância dos dados em apreço é dada pelo valor do desvio padrão ao quadrado.</p>', 'julgue o item a seguir, relativo a esses dados.
A variância dos dados em apreço é dada pelo valor do desvio padrão ao quadrado.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', '', false);
INSERT INTO public.questao VALUES (39764, 2006, 4084, '695549', NULL, 'CEBRASPE', '<p style="text-align: left;">Cinco municípios de um estado brasileiro possuem as seguintes quantidades de patrimônios históricos: {2, 3, 5, 3, 2}.</p><p style="text-align: left;"><br/>
Admitindo que a média e o desvio-padrão desse conjunto de valores sejam iguais a 3 e 1,2, respectivamente, julgue o item seguinte.</p><p style="text-align: left;"><br/>
Para esse conjunto de valores, a variância é igual a 3.</p>', 'julgue o item seguinte.
Para esse conjunto de valores, a variância é igual a 3.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (39765, 2006, 4084, '359443', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando que um auditor fiscal encarregado de analisar indícios de irregularidades em obras de um determinado estado tenha analisado 50 obras e constatado irregularidades em 40 delas, julgue o item a seguir.</p><p style="text-align: left;"><br/>
O desvio padrão da amostra foi inferior a 0,05.</p>', 'julgue o item a seguir.
O desvio padrão da amostra foi inferior a 0,05.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (40127, 2007, 4092, '2975103', NULL, 'CEBRASPE', '<p style="text-align: left;">P: “Se não consigo vencê-lo, me juntarei a ele.”</p><p style="text-align: left;"><br/>
Julgue o item seguinte, relativo à proposição P, acima apresentada.</p><p style="text-align: left;">A negação da proposição P pode ser corretamente expressa por “Se consigo vencê-lo, não me juntarei a ele.”.</p>', 'Julgue o item seguinte, relativo à proposição P, acima apresentada.
