INSERT INTO public.questao VALUES (39465, 2006, 4072, '1727039', NULL, 'CEBRASPE', '<p style="text-align: left;">Em determinado dia, em uma região atendida por uma unidade do corpo de bombeiros, ocorreram 16 acidentes, que resultaram em 48 vítimas, socorridas pelos bombeiros nos próprios locais de acidente. Entre essas vítimas, 4 vieram a óbito no momento do atendimento, e as demais sobreviveram.</p><p style="text-align: left;">Com base nessa situação hipotética, julgue o item a seguir.</p><p style="text-align: left;">Suponha que as idades das vítimas que vieram a óbito sejam 12, 50, 30 e 20 anos de idade. Nesse caso, a mediana das idades é maior que 26 anos.</p>', 'julgue o item a seguir.
Suponha que as idades das vítimas que vieram a óbito sejam 12, 50, 30 e 20 anos de idade. Nesse caso, a mediana das idades é maior que 26 anos.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
