INSERT INTO public.questao VALUES (39557, 2007, 4076, '127272', NULL, 'CEBRASPE', '<p style="text-align: left;">Paulo, Tiago e João, auditores do trabalho, nasceram, um deles em Brasília, o outro, em Goiânia e o terceiro, em Curitiba. Suas idades são 25, 27 e 28 anos. Sabe-se que João não nasceu em Brasília e não tem 25 anos; que o auditor que nasceu em Goiânia tem 28 anos; que Paulo não nasceu em Curitiba nem tem 25 anos; e que Tiago nasceu na região Centro-Oeste.</p><p style="text-align: left;">Com base nessas informações, julgue o seguinte item.</p><p style="text-align: left;">O auditor brasiliense tem 27 anos.</p>', 'julgue o seguinte item.
O auditor brasiliense tem 27 anos.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
