INSERT INTO public.questao VALUES (39560, 2007, 4076, '162092', NULL, 'CEBRASPE', '<p style="text-align: left;">
	Mara, Júlia e Lina são assessoras em um tribunal. Uma delas ocupa a função de cerimonialista, outra, de assessora de assuntos internacionais e a outra, de analista processual. Uma dessas assessoras ocupa a sua função há exatos 11 anos, outra, há exatos 13 anos, e a outra, há exatos 20 anos. Sabe-se, ainda, que:</p><ul><li>
		Mara não é a cerimonialista e não é a assessora que exerce a função há exatos 11 anos;</li><li>
		a analista processual ocupa a função há exatos 20 anos;</li><li>
		Júlia não é a assessora de assuntos internacionais nem é a assessora que ocupa a função há exatos 13 anos;</li><li>
		Lina ocupa a função há exatos 13 anos.</li></ul><p style="text-align: left;"><br/>
	Com base nessa situação hipotética, julgue o item subsequente.</p><p style="text-align: left;"><br/>
	A assessora de assuntos internacionais ocupa a função há exatos 11 anos.</p>', 'julgue o item subsequente.
	A assessora de assuntos internacionais ocupa a função há exatos 11 anos.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
