INSERT INTO public.questao VALUES (39563, 2007, 4076, '212209', NULL, 'CEBRASPE', '<p style="text-align: left;">
	O Flamengo, o Corinthians e o Cruzeiro foram convidados para jogos amistosos de futebol contra times europeus. Os jogos serão realizados em Lisboa, em Roma e em Paris, nos dias 22, 23 e 24 de agosto. Além disso, sabe-se que:</p><p style="text-align: left; margin-left: 40px;"><br/>
	►cada clube jogará apenas uma vez;<br/>
	►somente um jogo acontecerá em cada dia;<br/>
	►em cada cidade ocorrerá apenas um jogo;<br/>
	►o Flamengo jogará em Roma;<br/>
	►o Cruzeiro jogará no dia 24;<br/>
	►o jogo do dia 23 será em Lisboa.</p><p style="text-align: left;"><br/>
	Considerando essa situação hipotética, julgue o item a seguir.</p><p style="text-align: left;"><br/>
	O Flamengo jogará no dia 22.</p>', 'julgue o item a seguir.
	O Flamengo jogará no dia 22.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', '', false);
