INSERT INTO public.questao VALUES (39566, 2007, 4076, '1546895', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de Fábio, Maria e Pedro, servidores de uma mesma organização, sabe-se que:</p><ul><li>um deles é contador; outro, gestor; outro, analista;</li><li>a idade de um deles é 25 anos; a de outro, 31 anos; a de outro, 33 anos;</li><li>Fábio é quem tem 31 anos de idade; e o gestor é quem está com 25 anos de idade.</li></ul><p style="text-align: left;">Com base nessas informações, julgue o item a seguir.</p><p style="text-align: left;">Se a soma da idade de Maria com a de Fábio for superior ao dobro da idade de Pedro, então, necessariamente, Pedro será o gestor.</p>', 'julgue o item a seguir.
Se a soma da idade de Maria com a de Fábio for superior ao dobro da idade de Pedro, então, necessariamente, Pedro será o gestor.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', '', false);
INSERT INTO public.questao VALUES (39567, 2007, 4076, '1546896', NULL, 'CEBRASPE', '<p style="text-align: left;">A respeito de Fábio, Maria e Pedro, servidores de uma mesma organização, sabe-se que:</p><ul><li>um deles é contador; outro, gestor; outro, analista;</li><li>a idade de um deles é 25 anos; a de outro, 31 anos; a de outro, 33 anos;</li><li>Fábio é quem tem 31 anos de idade; e o gestor é quem está com 25 anos de idade.</li></ul><p style="text-align: left;">Com base nessas informações, julgue o item a seguir.</p><p style="text-align: left;">Se Pedro for o analista, então Maria será a mais jovem dos três servidores.</p>', 'julgue o item a seguir.
Se Pedro for o analista, então Maria será a mais jovem dos três servidores.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', '', false);
INSERT INTO public.questao VALUES (39568, 2007, 4076, '2600224', NULL, 'CEBRASPE', '<div style="display: block; border: 1px solid #ddd; padding: 10px; margin: 10px 0;"><p style="text-align: left;">No Festival Internacional de Campos do Jordão, estiveram presentes os músicos Carlos, Francisco, Maria e Isabel. Um deles é brasileiro, outro é mexicano, outro é chileno e outro, peruano.</p><p style="text-align: left;">Um deles tem 18 anos de idade, outro, 20, outro, 21 e o outro, 23.</p><p style="text-align: left;">Cada um desses músicos é especialista em um dos instrumentos: flauta, violino, clarinete e oboé. Sabe-se que Carlos não é brasileiro, tem 18 anos de idade e não é flautista; Francisco é chileno, não tem 20 anos de idade e é especialista em oboé; Maria tem 23 anos de idade e não é clarinetista; Isabel é mexicana e não é clarinetista; e o flautista tem mais de 20 anos de idade.</p></div><p style="text-align: left;">Com base nessas informações, julgue o item a seguir.</p><p style="text-align: left;">Carlos é mexicano.</p>', 'julgue o item a seguir.
Carlos é mexicano.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
