INSERT INTO public.questao VALUES (39584, 2007, 4076, '3001729', NULL, 'CEBRASPE', '<div style="display: block; border: 1px solid #ddd; padding: 10px; margin: 10px 0;"><p style="text-align: left;">Uma equipe de 10 profissionais, composta por 2 juízes,4 promotores 4 defensores públicos, atuou durante quatro dias em julgamento de processos em determinado do tribunal. A cada dia atuaram 1 juiz, 1 promotor e 1 defensor público. Na escala de trabalho, consta que Gerson, Maria o Júlia atuaram na segunda-feira; Luiz, Paula e Carlos atuaram terça-feira; Bianca e Adalberto atuaram na quana-feira; Luiz e Diogo atuaram na quinta feira,</p></div><p style="text-align: left;">Nessa situação, sabendo que Edna é defensora pública e atuou na quarta ou quinta-feira, que juíza Mania atuou em 2 dias, que Gerson e Bianca são promotores e que 3 promotores são do sexo masculino, Julgue o item seguinte.</p><p style="text-align: left;">Diogo e Carlos são promotores.    </p>', 'Julgue o item seguinte.
Diogo e Carlos são promotores.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', '', false);
