INSERT INTO public.questao VALUES (39587, 2007, 4076, '3011817', NULL, 'CEBRASPE', '<p style="text-align: left;">As atividades de manutenção, operação e instalação de sistemas na área de informática de um escritório são desenvolvidas por Edson, Humberto e Danilo; cada um é responsável por uma única atividade. Os seus salários são: R$ 2.300, R$ 2.400,00 e R$ 2.500,00. Sabe-se que o responsável pela instalação de sistemas, que é irmão de Danilo, não em o maior salário; Edson é o operador de sistemas, o responsável pela manutenção tem o menor salário.</p><p style="text-align: left;">Com base nessa situação hipotética, Julgue o item seguinte.</p><p style="text-align: left;">Danilo é o operador de sistemas.</p>', 'Julgue o item seguinte.
Danilo é o operador de sistemas.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
