INSERT INTO public.questao VALUES (39606, 2007, 4077, '684407', NULL, 'CEBRASPE', '<p style="text-align: left;">Os indivíduos S1, S2, S3 e S4, suspeitos da prática de um ilícito penal, foram interrogados, isoladamente, nessa mesma ordem. No depoimento, com relação à responsabilização pela prática do ilícito, S1 disse que S2 mentiria; S2 disse que S3 mentiria; S3 disse que S4 mentiria.</p><p style="text-align: left;"><br/>
A partir dessa situação, julgue o item a seguir.</p><p style="text-align: left;"><br/>
Se S4 disser que S1, S2 e S3 mentiram, então, na verdade, apenas ele e S2 mentiram</p>', 'julgue o item a seguir.
Se S4 disser que S1, S2 e S3 mentiram, então, na verdade, apenas ele e S2 mentiram', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', '', false);
INSERT INTO public.questao VALUES (39595, 2007, 4076, '578487', NULL, 'CEBRASPE', '<p style="text-align: left;">
	Uma empresa incentiva o viver saudável de seus funcionários. Para isso, dispensa mais cedo, duas vezes por semana, aqueles envolvidos em alguma prática esportiva. Aproveitando a oportunidade, Ana, Bia, Clara e Diana decidiram se associar a uma academia de ginástica, sendo que escolheram atividades diferentes, quais sejam, musculação, ioga, natação e ginástica aeróbica. O intuito é manter a forma e, se possível, perder peso. No momento, o peso de cada funcionária assume um dos seguintes valores: 50 kg, 54 kg, 56 kg ou 60 kg.</p><p style="text-align: left;">
	O que também se sabe é que:</p><p style="margin-left: 40px; text-align: left;"><strong>(a)</strong> Ana não faz musculação e não pesa 54 kg.</p><p style="margin-left: 40px; text-align: left;"><br/><strong>(b)</strong> Bia faz ioga e não tem 50 kg.</p><p style="margin-left: 40px; text-align: left;"><br/><strong>(c)</strong> A jovem que faz musculação pesa 56 kg e não é a Clara.</p><p style="margin-left: 40px; text-align: left;"><br/><strong>(d) </strong>A jovem com 54 kg faz natação.</p><p style="text-align: left;">
	Com base nessas informações, é correto afirmar que Diana faz musculação.</p>', 'Uma empresa incentiva o viver saudável de seus funcionários. Para isso, dispensa mais cedo, duas vezes por semana, aqueles envolvidos em alguma prática esportiva. Aproveitando a oportunidade, Ana, Bia, Clara e Diana decidiram se associar a uma academia de ginástica, sendo que escolheram atividades diferentes, quais sejam, musculação, ioga, natação e ginástica aeróbica. O intuito é manter a forma e, se possível, perder peso. No momento, o peso de cada funcionária assume um dos seguintes valores: 50 kg, 54 kg, 56 kg ou 60 kg.</p><p style="text-align: left;">
	O que também se sabe é que:</p><p style="margin-left: 40px; text-align: left;"><strong>(a)</strong> Ana não faz musculação e não pesa 54 kg.</p><p style="margin-left: 40px; text-align: left;"><br/><strong>(b)</strong> Bia faz ioga e não tem 50 kg.</p><p style="margin-left: 40px; text-align: left;"><br/><strong>(c)</strong> A jovem que faz musculação pesa 56 kg e não é a Clara.</p><p style="margin-left: 40px; text-align: left;"><br/><strong>(d) </strong>A jovem com 54 kg faz natação.</p><p style="text-align: left;">
	Com base nessas informações, é correto afirmar que Diana faz musculação.</p>', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', '', false);
