INSERT INTO public.questao VALUES (39711, 2006, 4083, '2591492', NULL, 'CEBRASPE', '<div style="overflow-x: auto; display: block"><table style="width: 400px; margin: 0px auto;"><tbody><tr><td style="text-align:center">0</td><td style="text-align:center">0</td><td style="text-align:center">1</td><td style="text-align:center">1</td><td style="text-align:center">1</td><td style="text-align:center">1</td><td style="text-align:center">1</td><td style="text-align:center">1</td><td style="text-align:center">0</td><td style="text-align:center">0</td></tr></tbody></table></div><p style="text-align: left;">A respeito do conjunto de dados precedente, constituído por 10 elementos, julgue o item a seguir.</p><p style="text-align: left;"><br/>
