INSERT INTO public.questao VALUES (39713, 2006, 4083, '2716127', NULL, 'CEBRASPE', '<p style="text-align: left;">Com base no conjunto de dados D = {0, 0, 1, 1, 2, 2, 2, 4, 6}, julgue o item seguinte.</p><p style="text-align: left;"><br/>
