INSERT INTO public.questao VALUES (39723, 2006, 4083, '3604780', NULL, 'CEBRASPE', '<p style="text-align: left;">Com relação aos métodos de estatística descritiva e de análise exploratória de dados, julgue o item a seguir.</p><p style="text-align: left;">Se, em uma tabela de frequências, determinada medida que varia de 0 a 15 for representada em intervalos de amplitude 5 e as frequências relativas acumuladas forem, respectivamente, 17%, 38% e 45%, então a média será igual à mediana.</p>', 'julgue o item a seguir.
Se, em uma tabela de frequências, determinada medida que varia de 0 a 15 for representada em intervalos de amplitude 5 e as frequências relativas acumuladas forem, respectivamente, 17%, 38% e 45%, então a média será igual à mediana.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (39724, 2006, 4083, '476422', NULL, 'CEBRASPE', '<p style="text-align: left;">Considere o seguinte conjunto de dados composto por cinco elementos: {82,93; 94,54; 98,40; 115,41; 123,07}.</p><p style="text-align: left;">Com base nesses dados, julgue o item subsequente acerca das medidas de tendência central.</p><p style="text-align: left;">A média do conjunto de dados em questão é 102,87 e a mediana é 98,40.</p><p style="text-align: left;">Se o valor 123,07 for alterado para 200, a média irá aumentar, mas a mediana continuará sendo 98,40.</p>', 'julgue o item subsequente acerca das medidas de tendência central.
