INSERT INTO public.questao VALUES (39737, 2006, 4084, '2780230', NULL, 'CEBRASPE', '<div style="overflow-x: auto; display: block"><table style="margin: 0px auto;"><tbody><tr><td style="background-color: rgb(238, 238, 238); text-align: center;"><p><strong>    X      </strong></p></td><td style="background-color: rgb(238, 238, 238); text-align: center;"><p><strong>frequência absoluta<br/>
