INSERT INTO public.questao VALUES (39739, 2006, 4084, '3186182', NULL, 'CEBRASPE', '<p style="text-align: left;">Em relação à estatística descritiva e à análise exploratória de dados, julgue os seguintes itens.</p><p style="text-align: left;">A variância amostral do conjunto de dados {10, 12, 12, 18, 18} é igual a 14.</p>', 'julgue os seguintes itens.
