INSERT INTO public.questao VALUES (39744, 2006, 4084, '2716130', NULL, 'CEBRASPE', '<p style="text-align: left;">Com base no conjunto de dados D = {0, 0, 1, 1, 2, 2, 2, 4, 6}, julgue o item seguinte.</p><p style="text-align: left;">O desvio padrão amostral do conjunto de dados é igual ou inferior a 1,6.</p>', 'julgue o item seguinte.
