INSERT INTO public.questao VALUES (39745, 2006, 4084, '2824386', NULL, 'CEBRASPE', '<p style="text-align: left;">A cana-de-açúcar chegou ao Brasil pelas mãos dos portugueses na década de 1530 e sempre foi um dos pilares de desenvolvimento econômico brasileiro.</p><p style="text-align: left;">O gráfico a seguir apresenta a produção total de cana-de-açúcar no Brasil, no período de 1975 a 2020.</p><p style="text-align:center"><div style="overflow-x: auto; display: inline-block; max-width: 100%; padding: 1px 0"><img src="https://cdn.tecconcursos.com.br/figuras/32d6e2c0-5a74-49c2-b628-3cccd6a1ccec"/></div></p><p style="text-align: left;">A partir dessas informações, julgue o item e faça o que se pede no item, que é do<strong> tipo B.</strong></p><p style="text-align: left;">O desvio padrão dos valores da produção nacional de cana-de-açúcar nos anos de 1995, 2000 e 2005 é superior a 22 milhões de toneladas.</p>', 'julgue o item e faça o que se pede no item, que é do
 tipo B.
O desvio padrão dos valores da produção nacional de cana-de-açúcar nos anos de 1995, 2000 e 2005 é superior a 22 milhões de toneladas.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', 'https://cdn.tecconcursos.com.br/figuras/32d6e2c0-5a74-49c2-b628-3cccd6a1ccec', false);
INSERT INTO public.questao VALUES (39746, 2006, 4084, '1937142', NULL, 'CEBRASPE', '<div style="overflow-x: auto; display: block"><table style="margin: 0px auto;"><tbody><tr><td style="background-color: rgb(238, 238, 238); text-align: center; width: 100px;"><strong>Tabela A</strong></td><td style="background-color: rgb(238, 238, 238); text-align: center; width: 100px;"></td></tr><tr><td style="text-align:center; width:100px">Classes</td><td style="text-align:center; width:100px">Freq.</td></tr><tr><td style="text-align:center; width:100px"><p>10-12</p></td><td style="text-align:center; width:100px">3</td></tr><tr><td style="text-align:center; width:100px"><p>12-14</p></td><td style="text-align:center; width:100px">7</td></tr><tr><td style="text-align:center; width:100px"><p>14-16</p></td><td style="text-align:center; width:100px">9</td></tr><tr><td style="text-align:center; width:100px"><p>16-18</p></td><td style="text-align:center; width:100px">12</td></tr><tr><td style="text-align:center; width:100px"><p>18-20</p></td><td style="text-align:center; width:100px">8</td></tr><tr><td style="text-align:center; width:100px"><p>20-22</p></td><td style="text-align:center; width:100px">6</td></tr><tr><td style="text-align:center; width:100px"><p>22-24</p></td><td style="text-align:center; width:100px">4</td></tr><tr><td style="text-align:center; width:100px"><p>24-26</p></td><td style="text-align:center; width:100px">2</td></tr></tbody></table></div><div style="overflow-x: auto; display: block"><table style="margin: 0px auto;"><tbody><tr><td style="background-color: rgb(238, 238, 238); text-align: center; width: 100px;"><p><strong>Tabela B</strong></p></td><td style="background-color: rgb(238, 238, 238); text-align: center;"></td></tr><tr><td style="text-align:center"><p>Classes</p></td><td style="text-align:center"><p>Freq.</p></td></tr><tr><td style="text-align:center"><p>2-4</p></td><td style="text-align:center">1</td></tr><tr><td style="text-align:center"><p>4-6</p></td