INSERT INTO public.questao VALUES (39796, 2008, 4085, '3237885', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando que, entre 900 candidatos ao cargo de agente de polícia civil, 630 tenham a habilidade de manuseio de arma de fogo e 480 tenham habilidade de cálculo, julgue o item a seguir.</p><p style="text-align: left;">Supondo-se que haja 70 vagas disponíveis, o número de maneiras de selecionar os referidos candidatos para preenchê-las é 900!/830!.</p>', 'julgue o item a seguir.
