INSERT INTO public.questao VALUES (39817, 2008, 4085, '2796933', NULL, 'CEBRASPE', '<p style="text-align: left;">Acerca de contagem, probabilidade e teoria de conjuntos, julgue o item a seguir.</p><p style="text-align: left;"><br/>
