INSERT INTO public.questao VALUES (39993, 2007, 4088, '2988080', NULL, 'CEBRASPE', '<p style="text-align: left;">Ao ser convidado por seu pai para uma viagem, Marcos assim respondeu:</p><p style="text-align: left;"><br/>
