INSERT INTO public.questao VALUES (39947, 2007, 4087, '109675', NULL, 'CEBRASPE', '<p style="text-align: left;">
	Nos termos da Lei n.º 8.666/1993, “É dispensável a realização de nova licitação quando não aparecerem interessados em licitação anterior e esta não puder ser repetida sem prejuízo para a administração”. Considerando apenas os aspectos desse mandamento atinentes à lógica e que ele seja cumprido se, e somente se, a proposição nele contida, — proposição P — for verdadeira, julgue o item seguinte.<br/><br/>
	A negação da proposição “A licitação anterior não pode ser repetida sem prejuízo para a administração” está corretamente expressa por “A licitação anterior somente poderá ser repetida com prejuízo para a administração”.</p>', 'julgue o item seguinte.
	A negação da proposição “A licitação anterior não pode ser repetida sem prejuízo para a administração” está corretamente expressa por “A licitação anterior somente poderá ser repetida com prejuízo para a administração”.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (39948, 2007, 4087, '127275', NULL, 'CEBRASPE', '<p style="text-align: left;">Julgue o item subsequente, relacionado a lógica proposicional.</p><p style="text-align: left;">A sentença “A presença de um órgão mediador e regulador das relações entre empregados e patrões é necessária em uma sociedade que busca a justiça social” é uma proposição simples.</p>', 'Julgue o item subsequente, relacionado a lógica proposicional.
A sentença “A presença de um órgão mediador e regulador das relações entre empregados e patrões é necessária em uma sociedade que busca a justiça social” é uma proposição simples.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', '', false);
