INSERT INTO public.questao VALUES (39977, 2007, 4088, '3492532', NULL, 'CEBRASPE', '<p style="text-align: left;">P: Se o condenado não for reincidente em crime doloso, tiver bons antecedentes e tiver cumprido mais de um terço da pena, pedirá o livramento condicional.</p><p style="text-align: left;">Com base na proposição P precedente, julgue o item que se seguem, considerando apenas os aspectos atinentes à lógica sentencial da proposição.</p><p style="text-align: left;">A tabela-verdade associada à proposição P possui mais de 15 linhas.</p>', 'julgue o item que se seguem, considerando apenas os aspectos atinentes à lógica sentencial da proposição.
A tabela-verdade associada à proposição P possui mais de 15 linhas.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', '', false);
