INSERT INTO public.questao VALUES (40139, 2007, 4092, '2271099', NULL, 'CEBRASPE', '<p style="text-align: left;">Considerando os conectivos lógicos usuais, que as letras maiúsculas representam proposições lógicas e que o símbolo ~ representa a negação de uma proposição, julgue o item subsecutivo.</p><p style="text-align: left;">A expressão (A ˅ B) → C é equivalente à expressão (~A ˄ ~B) ˅ C.</p>', 'julgue o item subsecutivo.
A expressão (A ˅ B) → C é equivalente à expressão (~A ˄ ~B) ˅ C.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'CERTO', '', false);
