INSERT INTO public.questao VALUES (40089, 2007, 4091, '550739', NULL, 'CEBRASPE', '<p style="text-align: left;">
	Considerando que as proposições lógicas sejam representadas por letras maiúsculas, julgue o próximo item, relativo a lógica proposicional e de argumentação.</p><p style="text-align: left;">
	A expressão [(P⟶Q) ∨ P]⟶Q é uma tautologia.</p>', 'julgue o próximo item, relativo a lógica proposicional e de argumentação.
	A expressão [(P⟶Q) ∨ P]⟶Q é uma tautologia.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (40090, 2007, 4091, '1298703', NULL, 'CEBRASPE', '<p style="text-align: left;">
