INSERT INTO public.questao VALUES (40146, 2007, 4092, '2637306', NULL, 'CEBRASPE', '<p style="text-align: left;">P1: “Se houver resistência de populares ou depredação de patrimônio, a polícia agirá.”<br/>
P2: “Se a polícia agir, a ambulância será necessária.”<br/>
P3: “Não houve depredação de patrimônio, mas a ambulância foi necessária.”<br/>
C: “Houve resistência de populares.”</p><p style="text-align: left;">Tomando por referência as proposições precedentes, julgue o item a seguir.</p><p style="text-align: left;">A proposição P2 é equivalente à proposição “Se a polícia não agir, a ambulância não será necessária.”.</p>', 'julgue o item a seguir.
A proposição P2 é equivalente à proposição “Se a polícia não agir, a ambulância não será necessária.”.', true, '2026-02-03 16:43:32.237649', '2026-02-03 16:43:32.237649', 'ERRADO', '', false);
INSERT INTO public.questao VALUES (40147, 2007, 4092, '2637308', NULL, 'CEBRASPE', '<p style="text-align: left;">P1: “Se houver resistência de populares ou depredação de patrimônio, a polícia agirá.”<br/>
P2: “Se a polícia agir, a ambulância será necessária.”<br/>
P3: “Não houve depredação de patrimônio, mas a ambulância foi necessária.”<br/>
C: “Houve resistência de populares.”</p><p style="text-align: left;">Tomando por referência as proposições precedentes, julgue o item a seguir.</p><p style="text-align: left;">A negação de P1 pode ser escrita como “Houve depredação de patrimônio ou a ambulância não foi necessária.”.</p>', 'julgue o item a seguir.
